// Decision film: the upsert path for Roam and Obsidian writes (ENG-2412). A silent film
// that lays out an engineering decision for two engineers: what Sid has answered and what
// is left for Michael. PLAN.md has the script and where each fact
// comes from; data.ts has every word on screen.
import { addCss, defineFilm } from "../../engine/runtime";
import kitCss from "../../kit/kit.css";
import css from "./film.css";
import { checkHeadlines } from "./headline";
import { play } from "./scenes";
import { DURATION } from "./timeline";
import { buildWorld } from "./world";

addCss(kitCss); // tokens, fonts' base, the stage
addCss(css); // this film's own look, after the kit

defineFilm(
  { title: "ENG-2412: the upsert path for Roam and Obsidian writes", width: 1280, height: 720, fps: 30, duration: DURATION },
  (f) => {
    play(buildWorld(f));
    checkHeadlines();
  },
);
import { startsOf, totalOf } from "../../kit";
import type { BeatId } from "./data";

// How long each beat runs, in seconds (PLAN.md, "Script"). A beat starts where the one
// before it ends, so one length moves every beat after it.
export const LENGTHS: Record<BeatId, number> = {
  b1: 8.5,
  b2: 11.5,
  b3: 25.0,
  b4: 12.5,
  b5: 13.5,
  b6: 16.0,
  b7: 11.5,
  b8: 10.5,
};

export const ORDER: BeatId[] = ["b1", "b2", "b3", "b4", "b5", "b6", "b7", "b8"];

export const T = startsOf(LENGTHS);

// Where each beat ends.
export const ENDS: Record<BeatId, number> = Object.fromEntries(
  ORDER.map((id) => [id, Math.round((T[id] + LENGTHS[id]) * 100) / 100]),
) as Record<BeatId, number>;

// Where the last beat ends. The film holds TAIL seconds past it.
export const END = totalOf(LENGTHS);
export const TAIL = 1.5;

// How many beats are built so far. The last one built keeps its slide and its headline
// to the end instead of leaving for the next beat.
export const BUILT = 8;

// Where the film ends with the beats built so far.
export const DURATION = ENDS[ORDER[BUILT - 1]] + TAIL;
// The headline band: one line at the top, built word by word. Copied from
// one-question/shared/helpers.ts (this film does not import from that series) with two
// changes: a headline can already be up at frame 0, and the last one can stay.
import { esc, html, type Film } from "../../engine/runtime";

export type Headline = { root: HTMLElement; words: HTMLElement[]; text: string };

export const headline = (f: Film, text: string): Headline => {
  const words = text
    .split(" ")
    .map((w) => `<span class="w">${esc(w)}</span>`)
    .join(" ");
  const root = html(`<div class="hl"><div class="hl-t">${words}</div></div>`);
  f.overlay.append(root);
  return { root, words: f.qa(".w", root) as HTMLElement[], text };
};

// At least 2.4 s, plus 0.3 s for each word past five.
export const holdFor = (h: Headline): number => 2.4 + 0.3 * Math.max(0, h.words.length - 5);

// Every headline's time on screen, from the start of its entrance to the end of its
// exit, so the film can refuse to build with two on screen at once.
const shown: Array<{ text: string; from: number; to: number }> = [];

export type SayOptions = {
  // false: already up at frame 0, no entrance (the poster frame).
  enter?: boolean;
  // false: stays to the end of the film.
  exit?: boolean;
};

// A headline arrives word by word and leaves as one. It shows from `at` until `until`,
// never shorter than its hold; returns when it is gone.
export const say = (f: Film, h: Headline, at: number, until: number, opts: SayOptions = {}): number => {
  const enter = opts.enter ?? true;
  const exit = opts.exit ?? true;
  if (enter) f.to(h.words, { opacity: [0, 1], y: [16, 0], blur: [6, 0] }, { at, dur: 0.5, ease: "arrive", stagger: 0.05 });
  else f.set(h.words, { opacity: 1 }, 0);
  if (!exit) {
    shown.push({ text: h.text, from: at, to: Infinity });
    return Infinity;
  }
  const end = Math.max(until, at + 0.5 + holdFor(h));
  const gone = f.to(h.root, { opacity: [1, 0], y: [0, -8], blur: [0, 4] }, { at: end, dur: 0.35, ease: "inQuad" });
  shown.push({ text: h.text, from: at, to: gone });
  return gone;
};

// Call once after every `say`: throws, naming both, if two headlines overlap.
export const checkHeadlines = (): void => {
  const sorted = [...shown].sort((a, b) => a.from - b.from);
  const clashes = sorted.slice(1).flatMap((h, i) =>
    h.from < sorted[i].to - 0.01
      ? [`"${sorted[i].text}" (to ${sorted[i].to.toFixed(2)} s) overlaps "${h.text}" (from ${h.from.toFixed(2)} s)`]
      : [],
  );
  if (clashes.length) throw new Error(`Headlines overlap:\n${clashes.join("\n")}`);
};
// This film's parts: stamps, ticket lines, boxes, arrows, tokens. HTML builders only;
// scenes animate what world.ts builds from them. Built film-locally (nothing here
// edits the kit). Classes start with dc- so they never touch a kit part.
import { esc } from "../../engine/runtime";
import { icon, refAttr } from "../../kit";
import { STAMP_LABEL, TICKETS, type StampKind, type TicketId } from "./data";

export type Rect = { x: number; y: number; w?: number; h?: number };

// Keep hyphenated words whole across a line break ("re-sends", "Marc-Antoine"); tags are left alone.
const keepHyphenated = (markup: string): string =>
  markup
    .split(/(<[^>]*>)/)
    .map((part) =>
      part.startsWith("<") ? part : part.replace(/\b[A-Za-z]{2,}-[A-Za-z]{2,}\b/g, (m) => `<span class="nb">${m}</span>`),
    )
    .join("");

// Escape text, and keep names and ticket IDs from breaking at their hyphens.
export const rich = (text: string): string =>
  keepHyphenated(esc(text)).replace(/\b(?:ENG|FEE)-\d+\b/g, (m) => `<span class="nb">${m}</span>`);

// left/top (and width/height) as an inline style, in design units.
export const at = (r: Rect, extra = ""): string =>
  `left:${r.x}px;top:${r.y}px${r.w !== undefined ? `;width:${r.w}px` : ""}${r.h !== undefined ? `;height:${r.h}px` : ""}${extra ? `;${extra}` : ""}`;

// ------------------------------------------------------------------ icons
// Three glyphs the kit does not have, drawn in the kit's icon style.
const LOCAL_ICONS = {
  database:
    '<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5V19A9 3 0 0 0 21 19V5"/><path d="M3 12A9 3 0 0 0 21 12"/>',
  key: '<circle cx="8" cy="15" r="4.6"/><path d="M11.4 11.6 20.5 2.5"/><path d="M16.5 6.5l3 3"/><path d="M13.6 9.4l2.4 2.4"/>',
  cookie:
    '<path d="M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5"/><path d="M8.5 8.5v.01"/><path d="M16 15.5v.01"/><path d="M12 12v.01"/><path d="M11 17v.01"/><path d="M7 14v.01"/>',
} as const;

export type LocalIcon = keyof typeof LOCAL_ICONS;

export const localIcon = (name: LocalIcon, size = 24, stroke = 2): string =>
  `<svg class="ic" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${LOCAL_ICONS[name]}</svg>`;

// ------------------------------------------------------------------ stamps
// `Sid's answer · <date>` and `Open: needs Michael`. The wording is in data.ts.
export const stampHtml = (kind: StampKind, opts: { ref?: string; date?: string; pos?: string } = {}): string => {
  const lead = kind === "open" ? icon("help", 28, 2.4) : "";
  const date = opts.date ? `<span class="dc-date">· ${esc(opts.date)}</span>` : "";
  return `<div class="dc-stamp dc-stamp--${kind}"${refAttr(opts.ref)}${opts.pos ? ` style="${opts.pos}"` : ""}>${lead}<span class="dc-stamp-l">${esc(STAMP_LABEL[kind])}</span>${date}</div>`;
};

// ------------------------------------------------------------------ tickets
// A ticket cited by ID and exact title. The ID is the part people search for.
export const ticketRowHtml = (id: TicketId, status?: string): string =>
  `<div class="dc-trow"><span class="dc-id">${id}</span><span class="dc-ttl">${esc(TICKETS[id])}</span>${status ? `<span class="dc-tstatus">${esc(status)}</span>` : ""}</div>`;

// The line of tickets a beat leans on, at the bottom of the frame.
export const ticketLineHtml = (ref: string, rows: Array<{ id: TicketId; status?: string }>, extra = ""): string =>
  `<div class="dc-tline" data-ref="${ref}">${rows.map((r) => ticketRowHtml(r.id, r.status)).join("")}${extra}</div>`;

// ------------------------------------------------------------------ arrows
export type ArrowKind = "ok" | "fail" | "plan";
export type ArrowSpec = {
  ref: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  kind?: ArrowKind;
  // fail only: how far along the line the call breaks, 0..1.
  breakAt?: number;
};

const HEAD_ARM = 15;
const HEAD_SPREAD = 0.5;

// A straight arrow with an open head. The SVG sits at the arrow's own box, so scenes
// move and fade it like any element: `.dc-ar-line` takes `draw` and `.dc-ar-head` fades in
// when the line arrives. The engine gives a tweened path pathLength=1, which rescales
// dash lengths, so a dashed path is never tweened itself: it lives in an SVG of its own
// and the scene fades that SVG. A failing arrow is therefore two SVGs: the line that
// goes out (`ref`) and the dotted part that never lands (`ref-rest`).
export const arrowSvg = (a: ArrowSpec): string => {
  const pad = 22;
  const minX = Math.min(a.x1, a.x2) - pad;
  const minY = Math.min(a.y1, a.y2) - pad;
  const w = Math.abs(a.x2 - a.x1) + pad * 2;
  const h = Math.abs(a.y2 - a.y1) + pad * 2;
  const pt = (x: number, y: number): string => `${(x - minX).toFixed(1)} ${(y - minY).toFixed(1)}`;
  const dx = a.x2 - a.x1;
  const dy = a.y2 - a.y1;
  const back = Math.atan2(dy, dx) + Math.PI;
  const head = `M${pt(a.x2 + Math.cos(back + HEAD_SPREAD) * HEAD_ARM, a.y2 + Math.sin(back + HEAD_SPREAD) * HEAD_ARM)}L${pt(a.x2, a.y2)}L${pt(a.x2 + Math.cos(back - HEAD_SPREAD) * HEAD_ARM, a.y2 + Math.sin(back - HEAD_SPREAD) * HEAD_ARM)}`;
  const svg = (cls: string, ref: string, paths: string): string =>
    `<svg class="dc-ar ${cls}"${refAttr(ref)} style="left:${minX}px;top:${minY}px;width:${w}px;height:${h}px" viewBox="0 0 ${w} ${h}">${paths}</svg>`;
  const kind = a.kind ?? "ok";
  if (kind === "fail") {
    const t = a.breakAt ?? 0.6;
    const bx = a.x1 + dx * t;
    const by = a.y1 + dy * t;
    return (
      svg("dc-ar--fail", a.ref, `<path class="dc-ar-line" d="M${pt(a.x1, a.y1)}L${pt(bx, by)}"/>`) +
      svg("dc-ar--rest", `${a.ref}-rest`, `<path d="M${pt(bx, by)}L${pt(a.x2, a.y2)}"/>`)
    );
  }
  if (kind === "plan") return svg("dc-ar--plan", a.ref, `<path d="M${pt(a.x1, a.y1)}L${pt(a.x2, a.y2)}"/><path class="dc-ar-solid" d="${head}"/>`);
  return svg("dc-ar--ok", a.ref, `<path class="dc-ar-line" d="M${pt(a.x1, a.y1)}L${pt(a.x2, a.y2)}"/><path class="dc-ar-head" d="${head}"/>`);
};

// What a call is named, set above its arrow.
export const arrowLabelHtml = (ref: string, r: Rect, text: string, cls = "dc-ar-label--mono"): string =>
  `<div class="dc-ar-label ${cls}"${refAttr(ref)} style="${at(r)}">${esc(text)}</div>`;

// The marker where a call breaks.
export const crossHtml = (ref: string, cx: number, cy: number): string =>
  `<div class="dc-cross"${refAttr(ref)} style="left:${cx - 17}px;top:${cy - 17}px">${icon("x", 20, 3.4)}</div>`;

// ------------------------------------------------------------------ boxes and tokens
export const boxHtml = (ref: string, r: Rect, inner: string, cls = ""): string =>
  `<div class="dc-box${cls ? ` ${cls}` : ""}"${refAttr(ref)} style="${at(r)}">${inner}</div>`;

// A small step on a path: "converts".
export const stepHtml = (ref: string, cx: number, cy: number, text: string): string =>
  `<div class="dc-step"${refAttr(ref)} style="left:${cx}px;top:${cy}px">${esc(text)}</div>`;

// A node's Concept or Content, or the Concept with its Content inside.
export const tokenHtml = (ref: string, r: Rect, label: string, cls = ""): string =>
  `<div class="dc-token${cls ? ` ${cls}` : ""}"${refAttr(ref)} style="${at(r)}"><span>${esc(label)}</span><i class="dc-tok-mark dc-tok-ok">${icon("check", 18, 3.4)}</i><i class="dc-tok-mark dc-tok-no">${icon("x", 18, 3.4)}</i></div>`;

export const nestHtml = (ref: string, r: Rect, outer: string, inner: string): string =>
  `<div class="dc-token dc-token--nest"${refAttr(ref)} style="${at(r)}"><span class="dc-nest-l">${esc(outer)}</span><span class="dc-token dc-token--inner">${esc(inner)}</span><i class="dc-tok-mark dc-tok-ok">${icon("check", 18, 3.4)}</i></div>`;

// The empty place in the database where a token lands.
export const slotHtml = (ref: string, r: Rect): string => `<div class="dc-slot"${refAttr(ref)} style="${at(r)}"></div>`;

// A dated pill: "Jul 17: Michael and Marc-Antoine agreed on one route".
export const datePillHtml = (ref: string, r: Rect, date: string, text: string): string =>
  `<div class="dc-pill"${refAttr(ref)} style="${at(r)}"><b>${esc(date)}:</b> ${rich(text)}</div>`;

// ------------------------------------------------------------------ chips, code, people (beats 4 to 8)
// A ticket ID as a chip: the same one the ticket line uses.
export const idChipHtml = (id: string, ref?: string): string => `<span class="dc-id"${refAttr(ref)}>${esc(id)}</span>`;

// A code name or a path, in mono.
export const codeChipHtml = (text: string, ref?: string): string => `<span class="dc-code"${refAttr(ref)}>${esc(text)}</span>`;

// A short date or tag chip: "May 31".
export const tagChipHtml = (text: string): string => `<span class="dc-tag">${esc(text)}</span>`;

// Text with `names in backticks` set in mono (a function or file name inside a sentence).
export const inlineCode = (text: string): string =>
  keepHyphenated(esc(text).replace(/`([^`]+)`/g, '<span class="dc-ic">$1</span>'));

// Text with ticket IDs in bold and kept whole at their hyphens, and Marc-Antoine kept whole.
export const withIds = (text: string): string =>
  keepHyphenated(esc(text)).replace(/\b(?:ENG|FEE)-\d+\b/g, (m) => `<b class="dc-idt">${m}</b>`);

export type Person = "michael" | "marc";

// A round mark with someone's initials. Michael is purple, the colour of "Open: needs Michael".
export const initialsHtml = (who: Person, ref?: string): string =>
  `<span class="dc-who dc-who--${who}"${refAttr(ref)}>${who === "michael" ? "M" : "MA"}</span>`;

// A quoted line in the ticket line: who said it, and what.
export const ticketQuoteHtml = (who: string, text: string): string =>
  `<div class="dc-trow dc-tquote"><b>${esc(who)}:</b><span>“${esc(text)}”</span></div>`;

import { esc, html, type Film } from "../../engine/runtime";
import { icon } from "../../kit";
import { B1, B2, B3, B4, B5, B6, B7, B8, HEADLINES, TICKETS, type BeatId } from "./data";
import { headline, type Headline } from "./headline";
import {
  arrowLabelHtml,
  arrowSvg,
  at,
  boxHtml,
  codeChipHtml,
  crossHtml,
  datePillHtml,
  idChipHtml,
  initialsHtml,
  inlineCode,
  localIcon,
  nestHtml,
  slotHtml,
  stampHtml,
  stepHtml,
  tagChipHtml,
  ticketLineHtml,
  ticketQuoteHtml,
  tokenHtml,
  withIds,
  type Rect,
} from "./parts";
import { BUILT, ORDER } from "./timeline";

export type World = {
  f: Film;
  slide: Partial<Record<BeatId, HTMLElement>>;
  h: Partial<Record<BeatId, Headline>>;
  // The element with data-ref=`ref` inside a beat's slide.
  q: (beat: BeatId, ref: string) => HTMLElement;
  // The part of an arrow, token or box named by a selector, inside a beat's slide.
  within: (beat: BeatId, ref: string, selector: string) => HTMLElement;
};

// ------------------------------------------------------------------ beat 1
const COUNT_X = [80, 660];
const COUNT_W = [540, 540];

const slide1 = (): string => {
  const chip = `<div class="dc-chipwrap" style="top:142px"><div class="dc-tchip" data-ref="chip"><span class="dc-id dc-id--big">${B1.ticket}</span><span class="dc-tchip-t">${esc(TICKETS[B1.ticket])}</span></div></div>`;
  const groups = B1.groups
    .map(
      (g, i) =>
        `<div class="dc-count" data-ref="g${i}" style="${at({ x: COUNT_X[i], y: 286, w: COUNT_W[i], h: 300 })}">
          <div class="dc-count-fill" data-ref="g${i}-fill"></div>
          <div class="dc-count-body">
            <div class="dc-count-n" data-ref="g${i}-n">${esc(g.n)}</div>
            ${stampHtml(g.stamp, { ref: `g${i}-stamp` })}
            <div class="dc-count-gloss" data-ref="g${i}-gloss">${esc(g.gloss)}</div>
          </div>
        </div>`,
    )
    .join("");
  return chip + groups;
};

// ------------------------------------------------------------------ beat 2
const LANE1 = { x: 56, y: 100, w: 1168, h: 176 };
const LANE2 = { x: 56, y: 288, w: 1168, h: 184 };
const PLUGIN_W = 260;
const PLUGIN_H = 50;

const slide2 = (): string => {
  // Lane 1, "Today": each plugin converts, then writes straight to Supabase.
  const p1y = [154, 212];
  const today =
    `<div class="dc-card dc-lane" data-ref="lane1" style="${at(LANE1)}"></div>` +
    `<div class="dc-lane-title" data-ref="lane1-title" style="left:84px;top:112px">${esc(B2.today.title)}</div>` +
    p1y.map((y, i) => arrowSvg({ ref: `t-arrow${i}`, x1: 352, y1: y + 25, x2: 974, y2: y + 25 })).join("") +
    p1y
      .map((y, i) => boxHtml(`t-plugin${i}`, { x: 84, y, w: PLUGIN_W, h: PLUGIN_H }, esc(B2.plugins[i]), "dc-box--plugin"))
      .join("") +
    p1y.map((y, i) => stepHtml(`t-step${i}`, 663, y + 25, B2.step)).join("") +
    boxHtml("t-db", { x: 984, y: 154, w: 204, h: 108 }, `<span class="dc-db-l">${localIcon("database", 26, 2)}${esc(B2.db)}</span>`, "dc-box--db dc-box--db-wide");

  // Lane 2, "The goal": the plugins send CrossApp types, one route converts and upserts once.
  const p2y = [342, 400];
  const goal =
    `<div class="dc-card dc-lane" data-ref="lane2" style="${at(LANE2)}"></div>` +
    `<div class="dc-lane-title" data-ref="lane2-title" style="left:84px;top:300px">${esc(B2.goal.title)}</div>` +
    `<div class="dc-lane-note" data-ref="goal-note" style="left:232px;top:300px">${esc(B2.goal.note)}</div>` +
    arrowSvg({ ref: "g-arrow0", x1: 352, y1: p2y[0] + 25, x2: 588, y2: 384 }) +
    arrowSvg({ ref: "g-arrow1", x1: 352, y1: p2y[1] + 25, x2: 588, y2: 408 }) +
    arrowSvg({ ref: "g-arrow2", x1: 784, y1: 396, x2: 976, y2: 396 }) +
    p2y.map((y, i) => boxHtml(`g-plugin${i}`, { x: 84, y, w: PLUGIN_W, h: PLUGIN_H }, esc(B2.plugins[i]), "dc-box--plugin")).join("") +
    boxHtml("g-route", { x: 596, y: 342, w: 180, h: 108 }, esc(B2.route), "dc-box--plan dc-box--route") +
    stepHtml("g-step", 880, 396, B2.step) +
    boxHtml("g-db", { x: 984, y: 342, w: 204, h: 108 }, `<span class="dc-db-l">${localIcon("database", 26, 2)}${esc(B2.db)}</span>`, "dc-box--db dc-box--db-wide") +
    arrowLabelHtml("g-label", { x: 352, y: 436, w: 236, h: 30 }, B2.goal.arrow, "dc-ar-label--text");

  // The history, as a timeline: Jul 17, Oct 9, then Sid's answer.
  const dots = [70, 494, 848]
    .map((x, i) => `<i class="dc-tl-dot${i === 2 ? " dc-tl-dot--now" : ""}" data-ref="dot${i}" style="left:${x}px;top:486px"></i>`)
    .join("");
  const history =
    `<div class="dc-tl-line" data-ref="tl-line" style="left:56px;top:491px;width:1168px"></div>` +
    dots +
    datePillHtml("pill0", { x: 56, y: 508, w: 400 }, B2.history[0].date, B2.history[0].text) +
    datePillHtml("pill1", { x: 480, y: 508, w: 330 }, B2.history[1].date, B2.history[1].text) +
    `<div class="dc-verdict dc-verdict--col" style="left:834px;top:508px;width:390px">` +
    stampHtml(B2.stamp.kind, { ref: "stamp", date: B2.stamp.date }) +
    `<div class="dc-answer" data-ref="answer">${esc(B2.stamp.answer)}</div></div>`;

  return today + goal + history + ticketLineHtml("tl", B2.tickets);
};

// ------------------------------------------------------------------ beat 3
// Two panels side by side. Inside each, from the left: the sync box, the arrows, the
// database box. Measurements are in the slide's own units; PLAN.md has the reasoning.
const PANEL = { y: 94, w: 564, h: 404 };
const PANEL_X = [56, 660];
const SYNC = { w: 136, h: 112 };
const DB = { w: 158, y: 188, h: 168 };
const ARROW_PAIR = [252, 322]; // where the two calls leave, down the sync box
const ZONE = { gap: 8, label: 216 }; // between the sync box and the database box

const slide3 = (): string => {
  const [ax, bx] = PANEL_X;
  const inner = (x0: number) => ({
    sync: x0 + 22,
    db: x0 + 22 + 520 - DB.w,
  });
  const a = inner(ax);
  const b = inner(bx);
  const arrowX = (x: ReturnType<typeof inner>) => ({
    x1: x.sync + SYNC.w + ZONE.gap,
    x2: x.db - ZONE.gap,
  });
  const aa = arrowX(a);
  const ba = arrowX(b);
  const labelX = (x: { x1: number; x2: number }) => Math.round((x.x1 + x.x2) / 2 - ZONE.label / 2);
  const syncY = Math.round((ARROW_PAIR[0] + ARROW_PAIR[1]) / 2 - SYNC.h / 2);
  const slotX = (x: ReturnType<typeof inner>) => x.db + 12;
  const slotW = DB.w - 24;
  const breakX = Math.round(aa.x1 + 0.62 * (aa.x2 - aa.x1));
  const bY = 278; // the one call of the right panel leaves at the middle of its slot

  const panels = PANEL_X.map(
    (x, i) => `<div class="dc-card dc-panel" data-ref="p${i ? "b" : "a"}" style="${at({ x, y: PANEL.y, w: PANEL.w, h: PANEL.h })}"></div>`,
  ).join("");

  const syncBox = (ref: string, x: number): string => boxHtml(ref, { x, y: syncY, w: SYNC.w, h: SYNC.h }, esc(B3.sync), "dc-box--sync");
  const dbBox = (ref: string, x: number): string =>
