export const buildWorld = (f: Film): World => {
  const slide: Partial<Record<BeatId, HTMLElement>> = {};
  const h: Partial<Record<BeatId, Headline>> = {};
  for (const id of ORDER.slice(0, BUILT)) {
    const build = SLIDES[id];
    if (!build) throw new Error(`Beat ${id} has no slide yet`);
    const el = html(`<section class="dc-slide" data-slide="${id}">${build()}</section>`);
    f.world.append(el);
    slide[id] = el;
    h[id] = headline(f, HEADLINES[id]);
  }
  const root = (beat: BeatId): HTMLElement => {
    const el = slide[beat];
    if (!el) throw new Error(`Beat ${beat} is not built`);
    return el;
  };
  return {
    f,
    slide,
    h,
    q: (beat, ref) => f.q<HTMLElement>(`[data-ref="${ref}"]`, root(beat)),
    within: (beat, ref, selector) => f.q<HTMLElement>(selector, f.q<HTMLElement>(`[data-ref="${ref}"]`, root(beat))),
  };
};
