const avatarFor = (who: Who): string =>
  who === "marc-antoine" ? roleAvatar("author", 30) : who === "michael" ? roleAvatar("reviewer", 30) : "";

export type CardSpec = {
  x?: number;
  y?: number;
  w?: number;
  // In the flow of a stack, not placed by x and y.
  flow?: boolean;
  who: Who;
  head?: string;
  // Who, where and when, in small type under the head.
  tag?: string;
  body?: string;
  // Verbatim words; the card adds the quotation marks unless `bare`.
  quote?: string;
  bare?: boolean;
  note?: string;
  dashed?: boolean;
};

export const card = (s: CardSpec): HTMLElement =>
  html(
    `<div class="ur-card who-${s.who}${s.dashed ? " dashed" : ""}${s.flow ? " flow" : ""}" data-card${
      s.flow ? "" : ` style="${place(s.x ?? 0, s.y ?? 0, s.w)}"`
    }>${
      s.head ? `<div class="ur-card-h">${avatarFor(s.who)}<b>${esc(s.head)}</b></div>` : ""
    }${s.tag ? `<div class="ur-meta">${esc(s.tag)}</div>` : ""}${s.body ? `<p class="ur-body">${esc(s.body)}</p>` : ""}${
      s.quote ? `<p class="ur-quote">${s.bare ? esc(s.quote) : `“${esc(s.quote)}”`}</p>` : ""
    }${s.note ? `<div class="ur-note">${esc(s.note)}</div>` : ""}</div>`,
  );

// ------------------------------------------------------------------ strokes

export const svgLayer = (): SVGSVGElement => {
  const svg = document.createElementNS(SVG_NS, "svg");
  svg.setAttribute("class", "ur-svg");
  svg.setAttribute("width", "1280");
  svg.setAttribute("height", "720");
  svg.setAttribute("viewBox", "0 0 1280 720");
  return svg;
};

const shape = (svg: SVGSVGElement, d: string, cls: string): SVGPathElement => {
  const path = document.createElementNS(SVG_NS, "path");
  path.setAttribute("d", d);
  path.setAttribute("class", cls);
  svg.append(path);
  return path;
};

export type Arrow = { line: SVGPathElement; head: SVGPathElement };

// A straight arrow with an open head, from one point to another. `dashed` arrows
// cannot be drawn on (the engine's draw uses the dash array): fade them in.
export const arrow = (svg: SVGSVGElement, from: Point, to: Point, o: { dashed?: boolean; cls?: string } = {}): Arrow => {
  const geom = arrowPath({ ...from, w: 0, h: 0 }, { ...to, w: 0, h: 0 }, { gap: 0, arm: 14, spread: 0.5 });
  const extra = o.cls ? ` ${o.cls}` : "";
  return {
    line: shape(svg, geom.d, `ur-ln${o.dashed ? " dashed" : ""}${extra}`),
    head: shape(svg, geom.head, `ur-hd${o.dashed ? " dashed" : ""}${extra}`),
  };
};

// A plain line (no head), such as the stem between two stacked chips.
export const stem = (svg: SVGSVGElement, from: Point, to: Point, cls = ""): SVGPathElement =>
  shape(svg, `M${from.x} ${from.y}L${to.x} ${to.y}`, `ur-ln${cls ? ` ${cls}` : ""}`);

// ------------------------------------------------------------------ pictures

export const envelope = (o: { x: number; y: number; candidate?: boolean }): HTMLElement =>
  html(
    `<div class="ur-env${o.candidate ? " cand" : ""}" style="${place(o.x, o.y)}"><svg width="46" height="34" viewBox="0 0 46 34" fill="none" aria-hidden="true"><rect x="2" y="2" width="42" height="30" rx="6" class="e-body"/><path d="M5 8 23 21 41 8" class="e-flap"/></svg></div>`,
  );

// The cylinder for the database: a lid and a body drawn as one svg, with the label over
// the body. A small cylinder takes a shallow lid so the label clears it.
export const cylinder = (x: number, y: number, w: number, h: number, label: string, lid = 26): HTMLElement => {
  const rx = (w - 5) / 2;
  return html(
    `<div class="ur-db" data-card style="${place(x, y, w, h)}"><svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true"><path d="M2.5 ${lid}V${h - lid}A${rx} ${lid - 2} 0 0 0 ${w - 2.5} ${h - lid}V${lid}Z"/><ellipse cx="${w / 2}" cy="${lid}" rx="${rx}" ry="${lid - 2}"/></svg><span style="top:${lid / 2}px">${esc(label)}</span></div>`,
  );
};

