// A statement of Sid's: the ink bar says whose it is.
export const sidNote = (text: string): HTMLElement => html(`<p class="ur-sid" data-card>${esc(text)}</p>`);
// Scene helpers for this film: headlines and their windows, small entrances, and the
// three checks that fail the build instead of a render: two headlines at once, text
// under 22 units or cut off or over something else, and a beat that reads too fast.
// The headline helpers start as copies of one-question/shared/helpers.ts (copied,
// not imported: that series may change).
import { esc, html, type Film } from "../../engine/runtime";
import { FRAME, LENGTHS, type BeatKey } from "./timeline";

// ------------------------------------------------------------------ text

export const quoted = (text: string): string => `“${text}”`;

export const wordCount = (text: string): number => text.trim().split(/\s+/).filter(Boolean).length;

// PLAN.md rule 3: 0.7 s plus 0.3 s a word to read a card.
export const readTime = (words: number): number => 0.7 + 0.3 * words;

// ------------------------------------------------------------------ headlines

export type Headline = { root: HTMLElement; words: HTMLElement[]; text: string; n: HTMLElement | null };

// The question at the top of a chapter, word by word. `n` puts the chapter's number
// in a circle to its left (the circle is not part of the headline).
export const headline = (parent: HTMLElement, f: Film, text: string, opts: { n?: number; title?: boolean } = {}): Headline => {
  const words = text
    .split(" ")
    .map((w) => `<span class="w">${esc(w)}</span>`)
    .join(" ");
  const root = html(
    `<div class="ur-hl${opts.title ? " title" : ""}">${opts.n ? `<span class="ur-n" data-card>${opts.n}</span>` : ""}<div class="ur-hl-t">${words}</div></div>`,
  );
  parent.append(root);
  return { root, words: f.qa(".w", root), text, n: root.querySelector<HTMLElement>(".ur-n") };
};

// PLAN.md rule 1 and the series' hold: at least 2.4 s, plus 0.3 s for each word past five.
export const holdFor = (h: Headline): number => 2.4 + 0.3 * Math.max(0, h.words.length - 5);

const shown: Array<{ text: string; from: number; to: number }> = [];

// A headline arrives word by word at `at` (or is already there, for frame 0) and stays
// until `until`, when its chapter has finished leaving.
export const say = (f: Film, h: Headline, at: number, until: number, opts: { instant?: boolean } = {}): void => {
  if (until - at < holdFor(h) - 1e-6)
    throw new Error(`Headline "${h.text}" shows ${(until - at).toFixed(2)} s; it needs at least ${holdFor(h).toFixed(2)} s`);
  if (!opts.instant) {
    // The chapter's number comes in with its first word, not before it.
    if (h.n) f.to(h.n, { opacity: [0, 1], scale: [0.6, 1] }, { at, dur: 0.4, ease: "pop" });
    f.to(h.words, { opacity: [0, 1], y: [16, 0], blur: [6, 0] }, { at, dur: 0.5, ease: "arrive", stagger: 0.05 });
  }
  shown.push({ text: h.text, from: at, to: until });
};

// Call once after every `say`: throws, naming both, if two headlines overlap.
export const checkHeadlines = (): void => {
  const sorted = [...shown].sort((a, b) => a.from - b.from);
  const clashes = sorted.slice(1).flatMap((h, i) =>
    h.from < sorted[i].to - 0.01
      ? [`"${sorted[i].text}" (to ${sorted[i].to.toFixed(2)} s) overlaps "${h.text}" (from ${h.from.toFixed(2)} s)`]
      : [],
  );
  if (clashes.length) throw new Error(`Headlines overlap:\n${clashes.join("\n")}`);
};

// ------------------------------------------------------------------ small motions

// Fade in with a short rise.
export const enter = (f: Film, el: Element | Element[], at: number, o: { dur?: number; rise?: number } = {}): number =>
  f.to(el, { opacity: [0, 1], y: [o.rise ?? 10, 0] }, { at, dur: o.dur ?? 0.5, ease: "arrive" });

// Fade in where it stands.
export const appear = (f: Film, el: Element | Element[], at: number, dur = 0.35): number =>
  f.to(el, { opacity: [0, 1] }, { at, dur, ease: "outQuad" });

// Fade out.
export const leave = (f: Film, el: Element | Element[], at: number, dur = 0.3): number =>
  f.to(el, { opacity: 0 }, { at, dur, ease: "outQuad" });

// A spring-in, for stamps and tags that should land.
export const land = (f: Film, el: Element | Element[], at: number, from = 0.7): number =>
  f.to(el, { opacity: [0, 1], scale: [from, 1] }, { at, dur: 0.4, ease: "pop" });

// Draw an SVG stroke from its start.
export const draw = (f: Film, path: Element | Element[], at: number, dur = 0.6): number =>
  f.to(path, { draw: [0, 1] }, { at, dur, ease: "inOutCubic" });

// ------------------------------------------------------------------ the checks

// PLAN.md rule 2: nothing meaningful under this size on the 1280 by 720 frame.
export const MIN_TEXT = 22;

// The headline band ends here; content starts at 130.
const HEADLINE_BOTTOM = 124;

const own = (el: Element): boolean =>
  [...el.childNodes].some((n) => n.nodeType === Node.TEXT_NODE && (n.textContent ?? "").trim() !== "");

const opacityOf = (el: Element): number => {
  let o = 1;
  for (let n: Element | null = el; n && n !== document.body; n = n.parentElement) {
    const cs = getComputedStyle(n);
    if (cs.display === "none" || cs.visibility === "hidden") return 0;
    o *= Number.parseFloat(cs.opacity);
  }
  return o;
};

const scaleOf = (el: Element): number => {
  let s = 1;
  for (let n: Element | null = el; n && !n.classList.contains("mo-stage"); n = n.parentElement) {
    const sc = getComputedStyle(n).scale;
    if (sc && sc !== "none") s *= Number.parseFloat(sc.split(" ")[0]);
  }
  return s;
};

type Box = { l: number; t: number; r: number; b: number };

// The box around an element's own text, not the width of the block that holds it.
const textBox = (el: Element): Box | null => {
  let box: Box | null = null;
  for (const node of el.childNodes) {
    if (node.nodeType !== Node.TEXT_NODE || (node.textContent ?? "").trim() === "") continue;
    const range = document.createRange();
    range.selectNodeContents(node);
    for (const r of range.getClientRects()) {
      if (r.width === 0 || r.height === 0) continue;
      box = box
        ? { l: Math.min(box.l, r.left), t: Math.min(box.t, r.top), r: Math.max(box.r, r.right), b: Math.max(box.b, r.bottom) }
        : { l: r.left, t: r.top, r: r.right, b: r.bottom };
    }
  }
  return box;
};

const rectBox = (el: Element): Box => {
  const r = el.getBoundingClientRect();
  return { l: r.left, t: r.top, r: r.right, b: r.bottom };
};

const overlap = (a: Box, b: Box): number => {
  const w = Math.min(a.r, b.r) - Math.max(a.l, b.l);
  const h = Math.min(a.b, b.b) - Math.max(a.t, b.t);
  return w > 0 && h > 0 ? w * h : 0;
};

const name = (el: Element): string => {
  const text = [...el.childNodes]
    .filter((n) => n.nodeType === Node.TEXT_NODE)
    .map((n) => (n.textContent ?? "").trim())
    .join(" ")
    .slice(0, 38);
  return `"${text}"`;
};

const inspect = (f: Film, label: string, t: number): void => {
  f.rectAt(f.world, t);
  const problems: string[] = [];
  // `box` is the text's own box; `core` trims 12% of the type size off the top and bottom,
  // because lines of a paragraph are closer together than their boxes are tall.
  const texts: Array<{ el: Element; box: Box; core: Box; card: Element | null }> = [];
  for (const el of f.world.querySelectorAll("*")) {
    if (!own(el) || el.closest("[data-nocheck]")) continue;
    if (opacityOf(el) < 0.95) continue;
    const box = textBox(el);
    if (!box) continue;
    const size = Number.parseFloat(getComputedStyle(el).fontSize) * scaleOf(el);
    if (size < MIN_TEXT - 0.01) problems.push(`${name(el)} is ${size.toFixed(1)} units, under ${MIN_TEXT}`);
    if (box.l < 4 || box.t < 4 || box.r > FRAME.w - 4 || box.b > FRAME.h - 4)
      problems.push(`${name(el)} is outside the frame (${Math.round(box.l)},${Math.round(box.t)} to ${Math.round(box.r)},${Math.round(box.b)})`);
    const card = el.closest("[data-card]");
    if (card) {
      const c = rectBox(card);
      if (box.l < c.l - 1.5 || box.r > c.r + 1.5 || box.t < c.t - 1.5 || box.b > c.b + 1.5)
        problems.push(`${name(el)} spills out of its card (${Math.round(box.r - c.r)} right, ${Math.round(box.b - c.b)} below)`);
    }
    if (el.closest(".ur-hl-t") && !el.closest(".ur-hl.title") && box.b > HEADLINE_BOTTOM)
      problems.push(`headline ends at ${Math.round(box.b)}, past ${HEADLINE_BOTTOM}`);
    const trim = size * 0.12;
    texts.push({ el, box, core: { l: box.l, r: box.r, t: box.t + trim, b: box.b - trim }, card });
  }
  for (let i = 0; i < texts.length; i += 1)
    for (let j = i + 1; j < texts.length; j += 1) {
      const a = texts[i];
      const b = texts[j];
      if (a.el.contains(b.el) || b.el.contains(a.el)) continue;
      if (overlap(a.core, b.core) > 6) problems.push(`${name(a.el)} overlaps ${name(b.el)}`);
    }
  const cards = [...f.world.querySelectorAll("[data-card]")].filter((c) => opacityOf(c) >= 0.95);
  for (const text of texts)
    for (const card of cards) {
      if (card.contains(text.el) || text.el.contains(card)) continue;
      if (overlap(text.core, rectBox(card)) > 6)
        problems.push(`${name(text.el)} runs over the card .${card.className.toString().trim().replace(/\s+/g, ".")} "${(card.textContent ?? "").trim().slice(0, 24)}"`);
    }
  if (problems.length) throw new Error(`Legibility at ${label}, ${t.toFixed(2)} s:\n  ${[...new Set(problems)].join("\n  ")}`);
};

// Looks at every visible piece of text at each time: at least 22 units, inside the
// frame and its own card, not over other text or another card. Pick times when the
// beat's entrances are done.
export const checkLegibility = (f: Film, label: string, times: number[]): void => {
  for (const t of times) f.job(t, () => inspect(f, label, t));
};

// Read words a second over a beat's length minus 2 s. PLAN.md rule 3 aims at 3.3 or less.
export const pace = (key: BeatKey, read: string[]): { words: number; rate: number; line: string } => {
  const words = read.reduce((n, text) => n + wordCount(text), 0);
  const rate = words / Math.max(1, LENGTHS[key] - 2);
  if (rate > 3.8) throw new Error(`${key} reads ${words} words in ${LENGTHS[key]} s (${rate.toFixed(2)} a second): too fast`);
  return { words, rate, line: `${words} read words, ${rate.toFixed(1)} a second` };
};

import { html, type Film } from "../../engine/runtime";
import { esc } from "../../kit";
import { PATH } from "./data";
import { headline, say, type Headline } from "./helpers";
import { arrow, box, chip, cylinder, marker, stamp, stem, svgLayer, tagPill, type Arrow, type Point } from "./parts";
import { EXIT, T, endOf, type BeatKey } from "./timeline";

// What every beat shares: the path (drawn in the "path" beat and shown again as the
// map), the rail of six numbers, and the shell of a chapter. Scenes add the rest.

// ------------------------------------------------------------------ the request path

// World coordinates of the path. The plugin is on the left, the route in the middle,
// the database on the right; every chapter's own drawing keeps those places.
export const LAYOUT = {
  top: 104,
  plugin: { x: 64, w: 304, h: 378 },
  route: { x: 508, w: 492, h: 354 },
  zone: { x1: 368, x2: 508 },
  db: { x: 1066, w: 150, h: 150 },
  step: { dx: 24, y0: 252, h: 36, gap: 14, w: 214 },
  postY: 208,
  responseY: 372,
  tests: { y: 500, h: 89 },
};

export type PathLayer = {
  root: HTMLElement;
  svg: SVGSVGElement;
  plugin: HTMLElement;
  chips: HTMLElement[];
  route: HTMLElement;
  steps: HTMLElement[];
  stems: SVGPathElement[];
  validateNote: HTMLElement;
  db: HTMLElement;
  tests: HTMLElement;
  post: Arrow;
  response: Arrow;
  call: Arrow;
  testsLink: Arrow;
  postLabel: HTMLElement;
  responseLabel: HTMLElement;
  markers: HTMLElement[];
};

const label = (text: string, x: number, y: number, cls = "", w?: number): HTMLElement =>
  html(
    `<div class="ur-lbl ${cls}" style="left:${x}px;top:${y}px${w === undefined ? "" : `;width:${w}px`}">${esc(text)}</div>`,
  );

export const buildPath = (f: Film): PathLayer => {
  const L = LAYOUT;
  const root = html('<div class="ur-path"></div>');
  f.world.append(root);
  // The strokes are added to the layer after the boxes, so arrows and stems draw over them.
  const svg = svgLayer();

  const pluginBox = box({
    x: L.plugin.x,
    y: L.top,
    w: L.plugin.w,
    h: L.plugin.h,
    title: PATH.plugin.title,
    lines: [{ html: esc(PATH.plugin.sub) }, { html: esc(PATH.plugin.fn), cls: "ink" }],
  });
  root.append(pluginBox);
  // Chips and steps sit inside their box, so positions are relative to its padding box.
  const chips = PATH.chips.map((text, i) =>
    chip(text, { x: 12, y: L.step.y0 - L.top - 2.5 + i * 44, w: L.plugin.w - 29 }),
  );
  pluginBox.append(...chips);

  const routeBox = box({
    x: L.route.x,
    y: L.top,
    w: L.route.w,
    h: L.route.h,
    title: PATH.route.title,
    lines: [
      { html: esc(PATH.route.address), cls: "mono ink" },
      { html: esc(PATH.route.pr), cls: "ink" },
      { html: esc(PATH.route.meta) },
    ],
  });
  root.append(routeBox);
  const steps = PATH.steps.map((text, i) =>
    chip(text, {
      x: L.step.dx - 2.5,
      y: L.step.y0 - L.top - 2.5 + i * (L.step.h + L.step.gap),
      w: L.step.w,
      cls: "step",
      dashed: text === "validate",
    }),
  );
  routeBox.append(...steps);
  const stepX = L.route.x + L.step.dx + L.step.w / 2;
  const stems = steps.slice(1).map((_, i) => {
    const y = L.step.y0 + i * (L.step.h + L.step.gap) + L.step.h;
    return stem(svg, { x: stepX, y }, { x: stepX, y: y + L.step.gap }, i < 2 ? "dashed" : "");
  });
  // Things that sit on a box are children of it, so their positions are relative to its
  // padding box (2.5 px inside the border).
  const inBox = (b: Point, x: number, y: number): Point => ({ x: x - b.x - 2.5, y: y - b.y - 2.5 });
  const routeAt = { x: L.route.x, y: L.top };
  const note = inBox(routeAt, L.route.x + L.step.dx + L.step.w + 16, L.step.y0 + L.step.h + L.step.gap + 5);
  const validateNote = label(PATH.validateNote, note.x, note.y);
  routeBox.append(validateNote);

  const upsertY = L.step.y0 + 3 * (L.step.h + L.step.gap) + L.step.h / 2;
  const dbBox = cylinder(L.db.x, upsertY - L.db.h / 2, L.db.w, L.db.h, PATH.db);
  root.append(dbBox);

  const testsBox = html(
    `<div class="ur-box row" data-card style="left:${L.route.x}px;top:${L.tests.y}px;width:${L.route.w}px;height:${L.tests.h}px"><div class="ur-box-t">${esc(PATH.tests.title)}</div><div class="stack"><div class="ur-box-l ink">${esc(PATH.tests.pr)}</div><div class="ur-box-l">${esc(PATH.tests.meta)}</div></div></div>`,
  );
  root.append(testsBox);

  root.append(svg);
  const post = arrow(svg, { x: L.zone.x1, y: L.postY }, { x: L.zone.x2, y: L.postY });
  const response = arrow(svg, { x: L.zone.x2, y: L.responseY }, { x: L.zone.x1, y: L.responseY });
  const callFrom = L.route.x + L.step.dx + L.step.w;
  const call = arrow(svg, { x: callFrom, y: upsertY }, { x: L.db.x, y: upsertY });
  const testsX = L.route.x + L.route.w / 2;
  const testsLink = arrow(svg, { x: testsX, y: L.tests.y }, { x: testsX, y: L.top + L.route.h });

  const mid = (L.zone.x1 + L.zone.x2) / 2;
  const postLabel = label(PATH.post, mid - 26, L.postY - 38, "ink");
  const responseLabel = label(PATH.response, mid - 48, L.responseY + 10, "ink");
  root.append(postLabel, responseLabel);

  const at2 = inBox(routeAt, L.route.x + 18 + 330, L.top + 48);
  const at3 = inBox(routeAt, L.route.x + L.step.dx + L.step.w + 16, L.step.y0 + 2 * (L.step.h + L.step.gap));
  const markers = [
    marker(1, mid - 18, L.postY + 26),
    marker(2, at2.x, at2.y),
    marker(3, at3.x, at3.y),
    marker(4, (L.route.x + L.route.w + L.db.x) / 2 - 18, upsertY - 42),
    marker(5, mid - 18, L.responseY - 60),
    marker(6, L.route.x + L.route.w + 12, L.tests.y + (L.tests.h - 36) / 2),
  ];
  root.append(markers[0], markers[3], markers[4], markers[5]);
  routeBox.append(markers[1], markers[2]);
  return { root, svg, plugin: pluginBox, chips, route: routeBox, steps, stems, validateNote, db: dbBox, tests: testsBox, post, response, call, testsLink, postLabel, responseLabel, markers };
};

// ------------------------------------------------------------------ the rail

export type Rail = { root: HTMLElement; nodes: HTMLElement[] };

export const buildRail = (f: Film): Rail => {
  const root = html(`<div class="ur-rail">${[1, 2, 3, 4, 5, 6].map((n) => `<i>${n}</i>`).join("")}</div>`);
  f.world.append(root);
  return { root, nodes: f.qa("i", root) };
};

const LIT = { backgroundColor: "#1f2733", borderColor: "#1f2733", color: "#ffffff" };
const PLAIN = { backgroundColor: "#ffffff", borderColor: "#cfd6e1", color: "#565f70" };

// The current number lit, the others plain: a finished chapter is not "done", it is open.
export const railTo = (f: Film, rail: Rail, n: number, at: number): void => {
  rail.nodes.forEach((node, i) => f.to(node, i === n - 1 ? LIT : PLAIN, { at, dur: 0.4, ease: "outCubic" }));
};

// ------------------------------------------------------------------ chapters

export type World = { f: Film; rail: Rail; path: PathLayer };

export const buildWorld = (f: Film): World => {
  const path = buildPath(f);
  const rail = buildRail(f);
  return { f, rail, path };
};

export type Chapter = {
  root: HTMLElement;
  head: Headline;
  left: HTMLElement;
  right: HTMLElement;
  tag: HTMLElement | null;
  stamp: HTMLElement;
};

export type ChapterSpec = {
  key: BeatKey;
  headline: string;
  // The chapter's number on the rail, 1 to 6; the title, path, map and list have none.
  n?: number;
  tag?: { text: string; gap?: boolean };
  title?: boolean;
  // The stamp is on every question chapter and nowhere else.
  noStamp?: boolean;
  // A chapter whose cards need other widths than the usual 596 left, 516 right.
  cols?: { left?: { x: number; w: number }; right?: { x: number; w: number } };
};

// The shell every beat has: a container that starts hidden (the title's starts shown,
// so frame 0 is the thumbnail), the headline, two columns, and the ticket tag and stamp
// at the foot, both hidden until a scene brings them in.
export const chapter = (f: Film, spec: ChapterSpec): Chapter => {
  const root = html(`<div class="ur-ch"${spec.title ? ' style="opacity:1"' : ""}></div>`);
  f.world.insertBefore(root, f.q(".ur-rail", f.world));
  const head = headline(root, f, spec.headline, { n: spec.n, title: spec.title });
  const left = html('<div class="ur-col left"></div>');
  const right = html('<div class="ur-col right"></div>');
  if (spec.cols?.left) left.style.cssText = `left:${spec.cols.left.x}px;width:${spec.cols.left.w}px`;
  if (spec.cols?.right) right.style.cssText = `left:${spec.cols.right.x}px;width:${spec.cols.right.w}px`;
  root.append(left, right);
  const tag = spec.tag ? tagPill(spec.tag.text, spec.tag.gap) : null;
  if (tag) root.append(tag);
  const mark = stamp();
  if (spec.noStamp) mark.remove();
  else root.append(mark);
  return { root, head, left, right, tag, stamp: mark };
};

// Show a chapter when its beat starts, say its headline 0.4 s in, and take it away
// over EXIT seconds ending at the beat's end (the last beat stays).
export const runChapter = (f: Film, ch: Chapter, key: BeatKey, o: { final?: boolean; instant?: boolean } = {}): void => {
  if (!o.instant) f.set(ch.root, { opacity: 1 }, T[key]);
  say(f, ch.head, o.instant ? T[key] : T[key] + 0.4, endOf(key), { instant: o.instant });
  if (!o.final) f.to(ch.root, { opacity: [1, 0] }, { at: endOf(key) - EXIT, dur: EXIT, ease: "inQuad" });
};
import { html } from "../../../engine/runtime";
import { esc, icon } from "../../../kit";
import { TITLE } from "../data";
import { checkLegibility, enter, land, pace } from "../helpers";
import { marker } from "../parts";
import { T } from "../timeline";
import { chapter, runChapter, type World } from "../world";

// Beat 0. Frame 0 already shows the headline and the ticket line: it is the thumbnail
// in Linear and Slack. The two plain lines come in after, then six open places.
export const title = (w: World): void => {
  const { f } = w;
  const t0 = T.title;
  const at = (s: number): number => t0 + s;

  const ch = chapter(f, { key: "title", headline: TITLE.headline, title: true, noStamp: true });
  runChapter(f, ch, "title", { instant: true });

  const ticket = html(
    `<div class="ur-ticket"><span class="ur-tag inline" data-card>${icon("ticket", 22, 2.2)}<span>${esc(TITLE.ticket)}</span></span><span>${esc(TITLE.ticketTitle)}</span></div>`,
  );
  const who = html(`<div class="ur-line" style="top:432px">${esc(TITLE.who)}</div>`);
  const status = html(`<div class="ur-line status" style="top:482px">${esc(TITLE.status)}</div>`);
  const six = html('<div class="ur-six"></div>');
  const marks = [1, 2, 3, 4, 5, 6].map((n) => marker(n, 0, 0));
  six.append(...marks);
  ch.root.append(ticket, who, status, six);

  f.beat("title", t0, {
    title: "Title",
    shows: "The headline and the ticket are on screen from frame 0; two plain lines and six numbered circles follow.",
    talk: [pace("title", [TITLE.who, TITLE.status]).line],
  });

  enter(f, who, at(1.5), { rise: 8 });
  enter(f, status, at(3.2), { rise: 8 });
  marks.forEach((m, i) => land(f, m, at(3.7 + i * 0.16), 0.5));

  checkLegibility(f, "title", [at(5.2)]);
};
