const lbl = (text: string, x: number, y: number, cls = "", w?: number): HTMLElement =>
  html(
    `<div class="ur-lbl ${cls}" style="left:${x}px;top:${y}px${w === undefined ? "" : `;width:${w}px`}">${esc(text)}</div>`,
