// Chapter 1: who is calling? The plugin signs in to Supabase itself; the route reads the
// website's cookies; a plugin call carries none. Nothing is on record, and the film
// draws no outcome for the candidate.
export const caller = (w: World): void => {
  const { f, rail } = w;
  const t0 = T.caller;
  const at = (s: number): number => t0 + s;

  const ch = chapter(f, { key: "caller", n: 1, headline: CALLER.headline, tag: { text: CALLER.tag, gap: true } });
  runChapter(f, ch, "caller");
  f.to(rail.root, { opacity: [0, 1] }, { at: at(0.5), dur: 0.4, ease: "outQuad" });
  railTo(f, rail, 1, at(0.5));

  f.beat("caller", t0, {
    title: `1 ${CALLER.headline}`,
    shows:
      "An envelope travels the POST arrow to the route; at its edge an empty cookie slot flashes, a red 401 lands and the envelope slides back. A dashed envelope then travels the same way and stops at a question mark; no outcome is drawn.",
    talk: [
      pace("caller", [
        CALLER.headline,
        CALLER.settled,
        CALLER.noOption,
        CALLER.candidateCard,
        CALLER.testCookie.text,
      ]).line,
    ],
  });

  // ---- left column: the case and the code. Coordinates are relative to the column.
  const left = ch.left;
  const svg = svgLayer();

  const pluginBox = box({
    x: 0,
    y: 0,
    w: 148,
    h: 262,
    cls: "tight",
    title: CALLER.plugin.title,
    lines: [{ html: esc(CALLER.plugin.sub) }, { html: esc(CALLER.plugin.what), cls: "ink" }],
  });
  const routeBox = box({
    x: 448,
    y: 0,
    w: 148,
    h: 262,
    cls: "tight",
    title: CALLER.route.title,
    lines: [{ html: esc(CALLER.route.what), cls: "ink" }],
  });
  left.append(pluginBox, routeBox, svg);

  const slot = html('<i class="ur-slot" style="left:441px;top:31px"></i>');
  const post = arrow(svg, { x: 152, y: 54 }, { x: 436, y: 54 });
  const postLabel = lbl(CALLER.post, 272, 8, "ink");
  const noCookie = lbl(CALLER.noCookie, 203, 78, "amber");
  const deny = html(`<div class="ur-deny" style="left:169px;top:114px">${esc(CALLER.denied)}</div>`);
  const env = envelope({ x: 158, y: 37 });

  const candLabel = lbl(CALLER.candidate.arrow, 148, 166, "ink center", 300);
  const candArrow = arrow(svg, { x: 152, y: 214 }, { x: 392, y: 214 }, { dashed: true });
  const candEnv = envelope({ x: 158, y: 197, candidate: true });
  const unknown = html('<div class="ur-q" style="left:398px;top:196px">?</div>');
  const candNote = lbl(CALLER.candidate.note, 148, 232, "center", 300);

  const pluginCite = html(`<div class="ur-row" style="left:0;top:282px">${cite(CALLER.plugin.cite)}</div>`);
  const routeCite = html(`<div class="ur-row" style="right:0;top:320px">${cite(CALLER.route.cite)}</div>`);
  const routeCite2 = html(`<div class="ur-row" style="right:0;top:358px">${cite(CALLER.route.cite2)}</div>`);

  left.append(slot, postLabel, noCookie, deny, env, candLabel, candEnv, unknown, candNote, pluginCite, routeCite, routeCite2);

  // ---- right column: what Sid settled, what is on record, and the one code fact that bears on it.
  const stack = html('<div class="ur-stack"></div>');
  const settled = card({ flow: true, who: "sid", body: CALLER.settled });
  const candidate = card({
    flow: true,
    who: "nobody",
    dashed: true,
    head: CALLER.noOption,
    body: CALLER.candidateCard,
  });
  const test = html(
    `<div class="ur-card who-nobody flow clip" data-card><p class="ur-body" style="margin-top:0">${esc(CALLER.testCookie.text)}</p><div class="ur-flowrow">${cite(CALLER.testCookie.cite)}</div><div class="ur-code flow bleed" data-card><div class="k-t-hi">${esc(CALLER.testCookie.code)}</div></div></div>`,
  );
  stack.append(settled, candidate, test);
  ch.right.append(stack);

  // ---- the order of things (seconds from the start of the beat)
  // The drawing starts in the middle of the frame and slides left to make room when the
  // record comes in. It keeps its size, so nothing in it drops under 22 units.
  f.set(left, { x: 278 }, 0);
  f.to(left, { x: 0 }, { at: at(4.0), dur: 0.7, ease: "inOutCubic" });
  enter(f, [pluginBox, routeBox], at(0.7), { rise: 10 });
  enter(f, [pluginCite, routeCite, routeCite2], at(1.3), { rise: 6 });
  enter(f, slot, at(1.2), { rise: 0 });
  enter(f, postLabel, at(1.8), { rise: 5 });
  draw(f, post.line, at(1.8), 0.5);
  appear(f, post.head, at(2.3), 0.15);

  // The first envelope goes in, finds no cookie, and comes back.
  appear(f, env, at(2.2), 0.2);
  f.to(env, { x: [0, 226] }, { at: at(2.3), dur: 0.9, ease: "inOutCubic" });
  f.to(slot, { scale: [1, 1.4] }, { at: at(3.2), dur: 0.15, ease: "outCubic" });
  f.to(slot, { scale: 1 }, { at: at(3.35), dur: 0.45, ease: "outBack" });
  enter(f, noCookie, at(3.2), { rise: 4 });
  land(f, deny, at(3.5), 0.75);
  f.to(env, { x: 0 }, { at: at(3.9), dur: 0.7, ease: "inOutCubic" });
  leave(f, env, at(4.5), 0.25);

  // What Sid settled comes in as the drawing makes room; the candidate is drawn meanwhile
  // (nobody has proposed it, and no outcome is drawn).
  enter(f, settled, at(4.4));
  enter(f, candLabel, at(5.0), { rise: 4 });
  appear(f, [candArrow.line, candArrow.head], at(5.0), 0.3);
  appear(f, candEnv, at(5.3), 0.2);
  f.to(candEnv, { x: [0, 170] }, { at: at(5.4), dur: 0.9, ease: "inOutCubic" });
  land(f, unknown, at(6.3), 0.6);
  enter(f, candNote, at(6.5), { rise: 4 });

  // What is on record: nothing, then the candidate; and the test's cookie.
  enter(f, candidate, at(9.0));
  enter(f, test, at(14.4));

  land(f, ch.stamp, at(17.8), 0.8);
  if (ch.tag) enter(f, ch.tag, at(0.6), { rise: 6 });

  // Times when the beat's entrances are in and the chapter has not started to leave.
  checkLegibility(f, "caller", [at(4.2), at(10.0), endOf("caller") - EXIT - 0.1]);
};
