// Decision film: every decision in the Architecture Decisions milestone of the Post-V0
// Roam–Obsidian sync architecture project (ENG-2416). A silent film that lays the decisions out
// for two engineers: what Sid has answered, what the tickets settle, and what is open, by owner.
// data.ts has every word on screen and the script; the look and the parts are copied from
// decision-upsert-path (untouched).
import { addCss, defineFilm } from "../../engine/runtime";
import kitCss from "../../kit/kit.css";
import css from "./film.css";
import { checkHeadlines } from "./headline";
import { play } from "./scenes";
import { DURATION } from "./timeline";
import { buildWorld } from "./world";

addCss(kitCss); // tokens, fonts' base, the stage
addCss(css); // this film's own look, after the kit

defineFilm(
  { title: "ENG-2416: where every Architecture Decision stands", width: 1280, height: 720, fps: 30, duration: DURATION },
  (f) => {
    play(buildWorld(f));
    checkHeadlines();
  },
);
// This film's parts: stamps, ticket lines, option cards, boxes, arrows, tokens. HTML builders
// only; scenes animate what world.ts builds from them. Copied from decision-upsert-path/parts.ts
// (that film is untouched) and extended: five stamps instead of two, option cards for "options on
// record", count rows, field chips. Classes start with dc- so they never touch a kit part.
import { esc } from "../../engine/runtime";
import { icon, refAttr } from "../../kit";
import { STAMP_LABEL, TICKETS, isOpen, type StampKind, type TicketId } from "./data";

export type Rect = { x: number; y: number; w?: number; h?: number };

// Keep hyphenated words whole across a line break ("re-sends", "Marc-Antoine"); tags are left alone.
const keepHyphenated = (markup: string): string =>
  markup
    .split(/(<[^>]*>)/)
    .map((part) =>
      part.startsWith("<") ? part : part.replace(/\b[A-Za-z]{2,}-[A-Za-z]{2,}\b/g, (m) => `<span class="nb">${m}</span>`),
    )
    .join("");

const ID_RE = /\b(?:ENG|FEE)-\d+\b/g;

// Rich text: escapes, sets `names in backticks` in mono, and keeps ticket IDs and hyphenated
// names whole at their hyphens. `bold` also makes ticket IDs bold.
export const rt = (text: string, bold = false): string =>
  text
    .split(/(`[^`]+`)/)
    .map((part) => {
      if (part.startsWith("`") && part.endsWith("`") && part.length > 2)
        return `<span class="dc-ic">${esc(part.slice(1, -1))}</span>`;
      const safe = keepHyphenated(esc(part));
      return safe.replace(ID_RE, (m) => (bold ? `<b class="dc-idt nb">${m}</b>` : `<span class="nb">${m}</span>`));
    })
    .join("");

// left/top (and width/height) as an inline style, in design units.
export const at = (r: Rect, extra = ""): string =>
  `left:${r.x}px;top:${r.y}px${r.w !== undefined ? `;width:${r.w}px` : ""}${r.h !== undefined ? `;height:${r.h}px` : ""}${extra ? `;${extra}` : ""}`;

// ------------------------------------------------------------------ icons
// Glyphs the kit does not have, drawn in the kit's icon style.
const LOCAL_ICONS = {
  database:
    '<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5V19A9 3 0 0 0 21 19V5"/><path d="M3 12A9 3 0 0 0 21 12"/>',
  key: '<circle cx="8" cy="15" r="4.6"/><path d="M11.4 11.6 20.5 2.5"/><path d="M16.5 6.5l3 3"/><path d="M13.6 9.4l2.4 2.4"/>',
  cookie:
    '<path d="M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5"/><path d="M8.5 8.5v.01"/><path d="M16 15.5v.01"/><path d="M12 12v.01"/><path d="M11 17v.01"/><path d="M7 14v.01"/>',
  user: '<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.2 3.6-7 8-7s8 2.8 8 7"/>',
  link: '<path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/>',
} as const;

export type LocalIcon = keyof typeof LOCAL_ICONS;

export const localIcon = (name: LocalIcon, size = 24, stroke = 2): string =>
  `<svg class="ic" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${LOCAL_ICONS[name]}</svg>`;

// ------------------------------------------------------------------ stamps
// Five stamps: Sid's answer (blue, with its date), Settled by the ticket (slate), and three Open
// stamps (purple). The wording is in data.ts. Open and Settled carry an icon so the text is not
// the only thing that says which is which.
export const stampHtml = (kind: StampKind, opts: { ref?: string; date?: string; pos?: string } = {}): string => {
  const lead = isOpen(kind) ? icon("help", 28, 2.4) : kind === "settled" ? icon("ticket", 28, 2.2) : "";
  const date = opts.date ? `<span class="dc-date">· ${esc(opts.date)}</span>` : "";
  const family = isOpen(kind) ? "open" : kind;
  return `<div class="dc-stamp dc-stamp--${family}"${refAttr(opts.ref)}${opts.pos ? ` style="${opts.pos}"` : ""}>${lead}<span class="dc-stamp-l">${esc(STAMP_LABEL[kind])}</span>${date}</div>`;
};

// A stamp and the answer beside it, as one block.
export const verdictHtml = (
  r: { x: number; y: number; w: number },
  kind: StampKind,
  date: string | undefined,
  answer: string | undefined,
  mod = "",
): string =>
  `<div class="dc-vd${mod ? ` ${mod}` : ""}" data-ref="verdict" style="${at({ x: r.x, y: r.y, w: r.w })}">` +
  stampHtml(kind, { ref: "stamp", date }) +
  (answer ? `<div class="dc-vd-t" data-ref="answer">${rt(answer, true)}</div>` : "") +
  `</div>`;

// ------------------------------------------------------------------ tickets
// A ticket cited by ID and exact title. The ID is the part people search for. `status` is a short
// chip after the title ("Ticket Draft").
export const ticketRowHtml = (id: TicketId, status?: string): string =>
  `<div class="dc-trow"><span class="dc-id">${id}</span><span class="dc-ttl">${rt(TICKETS[id])}</span>${status ? `<span class="dc-tstatus">${esc(status)}</span>` : ""}</div>`;

// A line in the ticket line that is not a ticket: who said it, and what, or a plain note.
export const ticketNoteHtml = (lead: string, text: string, quoted = true): string =>
  `<div class="dc-trow dc-tquote"><b>${esc(lead)}</b><span>${quoted ? `“${esc(text)}”` : esc(text)}</span></div>`;

// The line of tickets a beat leans on, at the bottom of the frame. A ticket is cited by ID and exact
// title the first time a chapter leans on it (forgetTickets() starts a chapter); after that it is an
// ID chip, so the same long title is not read again and again.
const cited = new Set<TicketId>();
export const forgetTickets = (): void => cited.clear();

export const ticketLineHtml = (
  ref: string,
  ids: readonly TicketId[],
  extra = "",
  status: Partial<Record<TicketId, string>> = {},
): string => {
  const known = ids.filter((id) => cited.has(id));
  const fresh = ids.filter((id) => !cited.has(id));
  ids.forEach((id) => cited.add(id));
  const chips = known.length
    ? `<div class="dc-trow dc-trow--ids">${known.map((id) => `<span class="dc-id">${id}</span>`).join("")}</div>`
    : "";
  return `<div class="dc-tline" data-ref="${ref}">${chips}${fresh.map((id) => ticketRowHtml(id, status[id])).join("")}${extra}</div>`;
};

// ------------------------------------------------------------------ arrows
export type ArrowKind = "ok" | "fail" | "plan";
export type ArrowSpec = {
  ref: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  kind?: ArrowKind;
  // fail only: how far along the line the call breaks, 0..1.
  breakAt?: number;
};

const HEAD_ARM = 15;
const HEAD_SPREAD = 0.5;

// A straight arrow with an open head. The SVG sits at the arrow's own box, so scenes move and
// fade it like any element: `.dc-ar-line` takes `draw` and `.dc-ar-head` fades in when the line
// arrives. The engine gives a tweened path pathLength=1, which rescales dash lengths, so a dashed
// path is never tweened itself: it lives in an SVG of its own and the scene fades that SVG. A
// failing arrow is therefore two SVGs: the line that goes out (`ref`) and the dotted part that
// never lands (`ref-rest`).
export const arrowSvg = (a: ArrowSpec): string => {
  const pad = 22;
  const minX = Math.min(a.x1, a.x2) - pad;
  const minY = Math.min(a.y1, a.y2) - pad;
  const w = Math.abs(a.x2 - a.x1) + pad * 2;
  const h = Math.abs(a.y2 - a.y1) + pad * 2;
  const pt = (x: number, y: number): string => `${(x - minX).toFixed(1)} ${(y - minY).toFixed(1)}`;
  const dx = a.x2 - a.x1;
  const dy = a.y2 - a.y1;
  const back = Math.atan2(dy, dx) + Math.PI;
  const head = `M${pt(a.x2 + Math.cos(back + HEAD_SPREAD) * HEAD_ARM, a.y2 + Math.sin(back + HEAD_SPREAD) * HEAD_ARM)}L${pt(a.x2, a.y2)}L${pt(a.x2 + Math.cos(back - HEAD_SPREAD) * HEAD_ARM, a.y2 + Math.sin(back - HEAD_SPREAD) * HEAD_ARM)}`;
  const svg = (cls: string, ref: string, paths: string): string =>
    `<svg class="dc-ar ${cls}"${refAttr(ref)} style="left:${minX}px;top:${minY}px;width:${w}px;height:${h}px" viewBox="0 0 ${w} ${h}">${paths}</svg>`;
  const kind = a.kind ?? "ok";
  if (kind === "fail") {
    const t = a.breakAt ?? 0.6;
    const bx = a.x1 + dx * t;
    const by = a.y1 + dy * t;
    return (
      svg("dc-ar--fail", a.ref, `<path class="dc-ar-line" d="M${pt(a.x1, a.y1)}L${pt(bx, by)}"/>`) +
      svg("dc-ar--rest", `${a.ref}-rest`, `<path d="M${pt(bx, by)}L${pt(a.x2, a.y2)}"/>`)
    );
  }
  if (kind === "plan") return svg("dc-ar--plan", a.ref, `<path d="M${pt(a.x1, a.y1)}L${pt(a.x2, a.y2)}"/><path class="dc-ar-solid" d="${head}"/>`);
  return svg("dc-ar--ok", a.ref, `<path class="dc-ar-line" d="M${pt(a.x1, a.y1)}L${pt(a.x2, a.y2)}"/><path class="dc-ar-head" d="${head}"/>`);
};

// What a call is named, set above its arrow.
