export type Opt = {
  ref: string;
  who?: Person;
  // "PR #1237 · Marc-Antoine · Jul 18": where it was proposed, by whom, when.
  meta?: string;
  title?: string;
  detail?: string;
  // Ticket IDs as chips, at the foot of the card.
  chips?: string[];
  state?: "plain" | "chosen" | "dropped";
  cls?: string;
};

// One option on record. `who` puts the proposer's initials before the meta line.
export const optHtml = (o: Opt): string => {
  const head =
    o.who || o.meta
      ? `<div class="dc-opt-who" data-ref="${o.ref}-who">${o.who ? personHtml(o.who, undefined, true) : ""}${o.meta ? `<span>${rt(o.meta)}</span>` : ""}</div>`
      : "";
  const title = o.title ? `<div class="dc-opt-t" data-ref="${o.ref}-t">${rt(o.title)}</div>` : "";
  const detail = o.detail ? `<div class="dc-opt-d" data-ref="${o.ref}-d">${rt(o.detail)}</div>` : "";
  const chips = o.chips && o.chips.length ? `<div class="dc-chips" data-ref="${o.ref}-chips">${o.chips.map((c) => idChipHtml(c)).join("")}</div>` : "";
  return `<div class="dc-opt${o.state && o.state !== "plain" ? ` is-${o.state}` : ""}${o.cls ? ` ${o.cls}` : ""}" data-ref="${o.ref}">${head}${title}${detail}${chips}</div>`;
};

