import { esc, html, type Film } from "../../engine/runtime";
import { CHAPTERS, HEADLINES, type ChapterId, type SceneId } from "./data";
import { headline, type Headline } from "./headline";
import { chapterPillHtml, counterHtml, forgetTickets } from "./parts";
import { slideAsks, slideK, slideOpen, slideRecap, slideTickets } from "./slides-frame";
import { slideU1, slideU2, slideU3, slideU4, slideU5, slideU6, slideU7, slideU8 } from "./slides-ch1";
import { slideC1, slideC10, slideC11, slideC2, slideC3, slideC4, slideC5, slideC6, slideC7, slideC8A, slideC8B, slideC9 } from "./slides-ch2";
import { slideR1, slideR2A, slideR2B, slideR3 } from "./slides-ch3";
import { ORDER, OWNER, counterText } from "./timeline";

export type World = {
  f: Film;
  slide: Record<SceneId, HTMLElement>;
  // The headline a scene shows: a scene without one of its own shares the one before it.
  h: Record<SceneId, Headline>;
  // The chapter pills at the top left, one per chapter that has one.
  pill: Partial<Record<ChapterId, HTMLElement>>;
  // The element with data-ref=`ref` inside a scene's slide.
  q: (scene: SceneId, ref: string) => HTMLElement;
  // The part of an arrow, token or box named by a selector, inside a scene's slide.
  within: (scene: SceneId, ref: string, selector: string) => HTMLElement;
  // Every element matching a selector inside a scene's slide.
  qa: (scene: SceneId, selector: string) => HTMLElement[];
};

const SLIDES: Partial<Record<SceneId, () => string>> = {
  open: slideOpen,
  k1: () => slideK("k1"),
  u1: slideU1,
  u2: slideU2,
  u3: slideU3,
  u4: slideU4,
  u5: slideU5,
  u6: slideU6,
  u7: slideU7,
  u8: slideU8,
  k2: () => slideK("k2"),
  c1: slideC1,
  c2: slideC2,
  c3: slideC3,
  c4: slideC4,
  c5: slideC5,
  c6: slideC6,
  c7: slideC7,
  c8a: slideC8A,
  c8b: slideC8B,
  c9: slideC9,
  c10: slideC10,
  c11: slideC11,
  k3: () => slideK("k3"),
  r1: slideR1,
  r2a: slideR2A,
  r2b: slideR2B,
  r3: slideR3,
  recap1: () => slideRecap("recap1"),
  recap2: () => slideRecap("recap2"),
  recap3: () => slideRecap("recap3"),
  tickets: slideTickets,
  asks: slideAsks,
};

// A scene with no slide yet shows its name, so the film still builds while it is being made.
const stub = (id: SceneId): string => `<div class="dc-sub" style="left:56px;top:300px">${esc(`(${id}: not built yet)`)}</div>`;

export const buildWorld = (f: Film): World => {
  const slide = {} as Record<SceneId, HTMLElement>;
  for (const id of ORDER) {
    if (CHAPTERS.some((c) => c.scenes[0] === id)) forgetTickets();
    const counter = counterText(id);
    const inner = (SLIDES[id] ?? ((): string => stub(id)))() + (counter ? counterHtml(counter) : "");
    const el = html(`<section class="dc-slide" data-slide="${id}">${inner}</section>`);
    f.world.append(el);
    slide[id] = el;
  }

  const own = {} as Record<SceneId, Headline>;
  for (const id of ORDER) {
    const text = HEADLINES[id];
    if (text) own[id] = headline(f, text);
  }
  const h = {} as Record<SceneId, Headline>;
  for (const id of ORDER) h[id] = own[OWNER[id]];

  const pill: Partial<Record<ChapterId, HTMLElement>> = {};
  for (const c of CHAPTERS) {
    if (!c.pill) continue;
    const el = html(chapterPillHtml(c.id, c.pill));
    f.overlay.append(el);
    pill[c.id] = el;
  }

  const root = (scene: SceneId): HTMLElement => slide[scene];
  return {
    f,
    slide,
    h,
    pill,
    q: (scene, ref) => f.q<HTMLElement>(`[data-ref="${ref}"]`, root(scene)),
    within: (scene, ref, selector) => f.q<HTMLElement>(selector, f.q<HTMLElement>(`[data-ref="${ref}"]`, root(scene))),
    qa: (scene, selector) => f.qa<HTMLElement>(selector, root(scene)),
  };
};
// The small moves every scene is made of, copied from decision-upsert-path/scenes.ts: a slide
// fading in and out, a stamp landing, a token popping, an arrow drawing itself, ticket rows
// arriving. No camera moves in this film: each scene is a full-frame composition.
import type { Film } from "../../engine/runtime";
import { reveal as kitReveal } from "../../kit";

// A checking aid, read through window.__arrivals by the pacing audit: when each piece of reading
// arrives (absolute seconds) and which elements it brings. The ticket line is reference text and
// is not recorded.
type Arrival = { at: number; els: Element[]; scene?: string };
const ARRIVALS: Arrival[] = [];
(globalThis as unknown as { __arrivals: Arrival[] }).__arrivals = ARRIVALS;
const note = (el: Element | Element[], at: number): void => {
  const els = (Array.isArray(el) ? el : [el]).filter((e) => !e.closest(".dc-tline"));
  if (els.length) ARRIVALS.push({ at, els, scene: (globalThis as unknown as { __scene?: string }).__scene });
};

export const reveal = (f: Film, el: Element | Element[], at: number, dur = 0.5, rise = 8): number => {
  note(el, at);
  return kitReveal(f, el, at, dur, rise);
};

export const slideIn = (f: Film, slide: Element, at: number): number =>
  f.to(slide, { opacity: [0, 1] }, { at, dur: 0.25, ease: "linear" });

export const slideOut = (f: Film, slide: Element, at: number): number =>
  f.to(slide, { opacity: 0 }, { at, dur: 0.35, ease: "inQuad" });

// A stamp lands: it arrives big and a little turned, and presses down.
export const land = (f: Film, el: Element, at: number): void => {
  note(el, at);
  f.to(el, { opacity: [0, 1] }, { at, dur: 0.1, ease: "linear" });
  f.to(el, { scale: [1.3, 1], rotate: [-4, 0] }, { at, dur: 0.42, ease: "outBack" });
};

// A token or a step settles into place.
export const pop = (f: Film, el: Element | Element[], at: number, dur = 0.4): number => {
  note(el, at);
  return f.to(el, { opacity: [0, 1], scale: [0.6, 1] }, { at, dur, ease: "pop" });
};

// A mark (check or cross) on a token.
export const mark = (f: Film, el: Element, at: number): number =>
  f.to(el, { opacity: [0, 1], scale: [0.3, 1] }, { at, dur: 0.3, ease: "pop" });

// An arrow draws itself from its tail. The SVG fades in at the first instant so a zero-length
// dash never shows, and the head arrives as the line does.
export const drawArrow = (f: Film, svg: Element, at: number, dur = 0.7): number => {
  const line = svg.querySelector(".dc-ar-line");
  if (!line) throw new Error("This arrow has no line to draw");
  f.to(svg, { opacity: [0, 1] }, { at, dur: 0.04, ease: "linear" });
  f.to(line, { draw: [0, 1] }, { at, dur, ease: "glide" });
  const head = svg.querySelector(".dc-ar-head");
  if (head) f.to(head, { opacity: [0, 1] }, { at: at + dur * 0.8, dur: 0.2, ease: "outQuad" });
  return at + dur;
};

// A dashed arrow (a planned one) is never drawn: it fades in as a whole.
export const fadeArrow = (f: Film, svg: Element, at: number, dur = 0.4): number =>
  f.to(svg, { opacity: [0, 1] }, { at, dur, ease: "outQuad" });

// The ticket line's rows arrive one after another.
export const rows = (f: Film, line: Element, at: number, gap = 0.18): void => {
  f.to(f.qa(".dc-trow", line), { opacity: [0, 1], y: [6, 0] }, { at, dur: 0.45, ease: "arrive", stagger: gap });
};

// A card or panel arrives: it fades in with a short rise.
export const card = (f: Film, el: Element | Element[], at: number, dur = 0.45, rise = 8): number => {
  note(el, at);
  return f.to(el, { opacity: [0, 1], y: [rise, 0] }, { at, dur, ease: "arrive" });
};

// Several cards arrive one after another.
export const cards = (f: Film, els: Element[], at: number, stagger = 0.1, dur = 0.45, rise = 8): number => {
  els.forEach((el, i) => note(el, at + i * stagger));
  return f.to(els, { opacity: [0, 1], y: [rise, 0] }, { at, dur, ease: "arrive", stagger });
};

// A ring on the option Sid's answer picks.
export const chosen = (f: Film, el: Element, at: number): void => f.cls(el, "is-chosen", { from: at });

// Layout check for this film: loads it in the browser, seeks to the settled moment of each scene (0.8 s
// before it ends, when everything has arrived) and flags what a look at stills would catch later.
//
//   cd discourse-graph/apps/roam
//   MOTION_DEPS_ROOT=$PWD npx tsx ../../../dg-films/motion/films/decision-milestone-eng2416/tools/check.ts          # every scene
//   ... check.ts u2 c8b                                                                                               # only these
//
// It flags: visible text under 24 px (stamps and answers under 32 px); text outside the frame or
// within 14 px of its edge; cards and boxes within 14 px of it; text outside the card or box it sits in; text over other text; cards and
// boxes that partly overlap each other; text sitting partly on a card it does not belong to. It does
// not replace looking at the frames. Exit code 1 when anything is flagged.
import path from "node:path";
import { pathToFileURL } from "node:url";
import { buildFilm } from "../../../engine/bundle";
import { loadPlaywright } from "../../../engine/deps";
import { ENDS, ORDER } from "../timeline";

const FILM = path.resolve(__dirname, "..");
const CACHE = path.resolve(FILM, "../../../output/motion/.cache");
const ids = process.argv.slice(2).filter((a) => !a.startsWith("--"));
const scenes = ids.length ? ids : ORDER;

// Runs in the page.
const analyse = (): string[] => {
  const stage = document.querySelector(".mo-stage") as HTMLElement;
  const W = 1280;
  const H = 720;
  const visible = (el: Element): number => {
    let o = 1;
    for (let e: Element | null = el; e && e !== document.body; e = e.parentElement) {
      const cs = getComputedStyle(e);
      if (cs.display === "none" || cs.visibility === "hidden") return 0;
      o *= parseFloat(cs.opacity);
    }
    return o;
  };
  const hasChrome = (el: Element): boolean => {
    const cs = getComputedStyle(el);
    const border = parseFloat(cs.borderTopWidth) + parseFloat(cs.borderLeftWidth) > 0 && cs.borderTopStyle !== "none";
    const bg = cs.backgroundColor;
    return border || (bg !== "rgba(0, 0, 0, 0)" && bg !== "transparent") || cs.boxShadow !== "none" || cs.backgroundImage !== "none";
  };
  const label = (el: Element): string => el.closest("[data-ref]")?.getAttribute("data-ref") ?? el.tagName.toLowerCase();
  const short = (s: string): string => (s.length > 38 ? `${s.slice(0, 36)}…` : s);

  type Item = { el: HTMLElement; txt: string; rects: DOMRect[]; fs: number };
  const items: Item[] = [];
  const walker = document.createTreeWalker(stage, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const n = walker.currentNode as Text;
    const txt = (n.textContent ?? "").trim();
    const el = n.parentElement;
    if (!txt || !el || el.closest("svg") || visible(el) < 0.6) continue;
    const range = document.createRange();
    range.selectNodeContents(n);
    const rects = [...range.getClientRects()].filter((r) => r.width > 0.5 && r.height > 0.5);
    if (rects.length) items.push({ el, txt, rects, fs: parseFloat(getComputedStyle(el).fontSize) });
  }
  const out: string[] = [];
  const ink = (r: DOMRect, fs: number) => ({ left: r.left, right: r.right, top: (r.top + r.bottom) / 2 - fs * 0.46, bottom: (r.top + r.bottom) / 2 + fs * 0.46 });

  for (const it of items) {
    const big = it.el.closest(".dc-stamp-l, .dc-vd-t");
    const min = big ? 32 : 24;
    if (it.fs < min - 0.05) out.push(`SIZE ${it.fs.toFixed(1)}px (< ${min}) "${short(it.txt)}" [${label(it.el)}]`);
  }
  for (const it of items)
    for (const r of it.rects) {
      if (r.left < -0.5 || r.top < -0.5 || r.right > W + 0.5 || r.bottom > H + 0.5) {
        out.push(`OFF-FRAME "${short(it.txt)}" [${label(it.el)}]`);
        break;
      }
      if (r.right > W - 14 || r.left < 14) {
        out.push(`EDGE (<14px) "${short(it.txt)}" [${label(it.el)}]`);
        break;
      }
    }
  for (const it of items) {
    let c: Element | null = it.el;
    while (c && c !== stage && !hasChrome(c)) c = c.parentElement;
    if (!c || c === stage || c.classList.contains("mo-stage")) continue;
    const cr = c.getBoundingClientRect();
    for (const r of it.rects) {
      const d = Math.max(cr.left - r.left, r.right - cr.right, cr.top - r.top, r.bottom - cr.bottom);
      if (d > 2.6) {
        out.push(`OVERFLOW "${short(it.txt)}" [${label(it.el)}] out of [${label(c)}] by ${Math.round(d)}px`);
        break;
      }
    }
  }
  for (let i = 0; i < items.length; i += 1)
    for (let j = i + 1; j < items.length; j += 1) {
      const a = items[i];
      const b = items[j];
      if (a.el.contains(b.el) || b.el.contains(a.el)) continue;
      let hit = false;
      for (const ra0 of a.rects)
        for (const rb0 of b.rects) {
          const ra = ink(ra0, a.fs);
          const rb = ink(rb0, b.fs);
          if (Math.min(ra.right, rb.right) - Math.max(ra.left, rb.left) > 2 && Math.min(ra.bottom, rb.bottom) - Math.max(ra.top, rb.top) > 3) hit = true;
        }
      if (hit) out.push(`TEXT-OVERLAP "${short(a.txt)}" [${label(a.el)}] x "${short(b.txt)}" [${label(b.el)}]`);
    }
  const boxes: Array<{ el: Element; r: DOMRect }> = [];
  stage
    .querySelectorAll<HTMLElement>(
      ".dc-card, .dc-box, .dc-opt, .dc-stat, .dc-pill, .dc-nt, .dc-warn, .dc-stamp, .dc-frow-c, .dc-half, .dc-file-r, .dc-calc, .dc-field, .dc-id, .dc-code, .dc-tag, .dc-eyebrow, .dc-quote, .dc-token, .dc-gauge, .dc-chpill, .dc-counter, .dc-refused, .dc-step",
    )
    .forEach((el) => {
      if (visible(el) < 0.6) return;
      const r = el.getBoundingClientRect();
      if (r.width >= 4 && r.height >= 4) boxes.push({ el, r });
    });
  const inside = (p: DOMRect, q: DOMRect) => p.left >= q.left - 1 && p.right <= q.right + 1 && p.top >= q.top - 1 && p.bottom <= q.bottom + 1;
  for (let i = 0; i < boxes.length; i += 1)
    for (let j = i + 1; j < boxes.length; j += 1) {
      const a = boxes[i];
      const b = boxes[j];
      if (a.el.contains(b.el) || b.el.contains(a.el)) continue;
      const w = Math.min(a.r.right, b.r.right) - Math.max(a.r.left, b.r.left);
      const h = Math.min(a.r.bottom, b.r.bottom) - Math.max(a.r.top, b.r.top);
      if (w > 3 && h > 3 && !inside(a.r, b.r) && !inside(b.r, a.r)) out.push(`BOX-OVERLAP [${label(a.el)}] x [${label(b.el)}] ${Math.round(w)}x${Math.round(h)}`);
    }
  // A card or box within 14 px of the frame's edge (the chapter label and the counter are meant to sit there).
  for (const b of boxes) {
    if (b.el.matches(".dc-chpill, .dc-counter")) continue;
    const r = b.r;
    if (r.left < 14 || r.top < 14 || r.right > W - 14 || r.bottom > H - 14) out.push(`BOX-EDGE (<14px) [${label(b.el)}] bottom ${Math.round(H - r.bottom)} right ${Math.round(W - r.right)}`);
  }
  // Text that sits partly on a card it is not part of (text that belongs on a card is fully inside it).
  for (const it of items)
    for (const b of boxes) {
      if (b.el.contains(it.el) || it.el.contains(b.el)) continue;
      if (b.el.matches(".dc-id, .dc-code, .dc-tag, .dc-field, .dc-token, .dc-step, .dc-refused, .dc-stamp, .dc-chpill, .dc-counter, .dc-eyebrow, .dc-warn, .dc-pill")) continue;
      for (const r0 of it.rects) {
        const r = ink(r0, it.fs);
        const w = Math.min(r0.right, b.r.right) - Math.max(r0.left, b.r.left);
        const h = Math.min(r.bottom, b.r.bottom) - Math.max(r.top, b.r.top);
        if (w > 4 && h > 3 && (h / (r.bottom - r.top) < 0.92 || w / (r0.right - r0.left) < 0.92)) {
          out.push(`TEXT-PARTLY-ON-BOX "${short(it.txt)}" [${label(it.el)}] over [${label(b.el)}]`);
          break;
        }
      }
    }
  return [...new Set(out)];
};

