"""cssdiff.py a.css b.css: rules by selector; same, changed, only-in-a, only-in-b."""
import re
import sys


def rules(path):
    text = re.sub(r"/\*.*?\*/", "", open(path).read(), flags=re.S)
    out = []
    for m in re.finditer(r"([^{}]+)\{([^{}]*)\}", text):
        sel = " ".join(m.group(1).split())
        decls = [d.strip() for d in m.group(2).split(";") if d.strip()]
        decls = [" ".join(d.split()) for d in decls]
        out.append((sel, decls))
    return out


a, b = rules(sys.argv[1]), rules(sys.argv[2])
da = {}
for s, d in a:
    da.setdefault(s, []).append(d)
db = {}
for s, d in b:
    db.setdefault(s, []).append(d)
same, changed = [], []
for s in da:
    if s in db:
        (same if da[s] == db[s] else changed).append(s)
print(f"rules a={len(a)} b={len(b)} same={len(same)} changed={len(changed)} only-a={len([s for s in da if s not in db])} only-b={len([s for s in db if s not in da])}")
print("\n== CHANGED")
for s in changed:
    print(f"-- {s}")
    for x, y in zip(da[s], db[s]):
        sx, sy = set(x), set(y)
        print("   a-only:", [d for d in x if d not in sy])
        print("   b-only:", [d for d in y if d not in sx])
    if len(da[s]) != len(db[s]):
        print(f"   count a={len(da[s])} b={len(db[s])}")
print("\n== ONLY IN A")
for s in da:
    if s not in db:
        print("  ", s)
print("\n== ONLY IN B")
for s in db:
    if s not in da:
        print("  ", s)

