import { html } from "../../../engine/runtime";
import { esc } from "../../../kit";
import { LIST } from "../data";
import { checkLegibility, enter, land, pace } from "../helpers";
import { card, tagPill } from "../parts";
import { T, clockOf, endOf } from "../timeline";
import { chapter, runChapter, type World } from "../world";

// The last beat: the six questions with the time each chapter starts and its ticket, the
// stamp once for all six, Michael's line about when the details get discussed, and what the
// film was checked against. The film holds on this frame.
export const list = (w: World): void => {
  const { f } = w;
  const t0 = T.list;
  const at = (s: number): number => t0 + s;

  const ch = chapter(f, { key: "list", headline: LIST.headline });
  runChapter(f, ch, "list", { final: true });

  f.beat("list", t0, {
    title: "Questions to answer before anyone builds",
    shows:
      "The six questions build line by line, each with the time its chapter starts and its ticket. The stamp lands once for all six, then Michael's line from 2026-07-30 and what the film was checked against. The film holds on this frame.",
    // The six questions repeat the chapter headlines and are an index, not reading.
    talk: [pace("list", [LIST.headline, LIST.quote]).line],
  });

  const rows = LIST.rows.map((row, i) => {
    const el = html(
      `<div class="ur-lrow" style="top:${130 + i * 58}px"><span class="ur-mk" data-card>${i + 1}</span><span class="q">${esc(row.question)}</span><span class="t">${clockOf(row.key)}</span></div>`,
    );
    el.append(tagPill(row.tag, row.tag === "No ticket"));
    return el;
  });
  const quote = card({ x: 64, y: 492, w: 900, who: "michael", tag: LIST.quoteWho, quote: LIST.quote });
  const footer = html(`<div class="ur-lbl" style="left:64px;top:612px">${esc(LIST.footer)}</div>`);
  ch.root.append(...rows, quote, footer);

  rows.forEach((row, i) => enter(f, row, at(0.7 + i * 0.45), { rise: 8 }));
  land(f, ch.stamp, at(3.6), 0.8);
  enter(f, quote, at(4.2));
  enter(f, footer, at(6.2), { rise: 4 });

  checkLegibility(f, "list", [endOf("list") - 0.1]);
};
import { html } from "../../../engine/runtime";
import { esc } from "../../../kit";
import { MAP } from "../data";
import { appear, checkLegibility, enter, leave, pace } from "../helpers";
import { EXIT, T, endOf } from "../timeline";
import { LAYOUT, chapter, runChapter, type World } from "../world";

// Beat 8: what has to be built. The path from the opening returns without its chips and
// markers, and each part that has a ticket takes the ticket's name. Solid means a ticket
// exists; dashed means none yet (the door, and the later moves of Roam sync, Obsidian sync
// and Roam publish).
export const map = (w: World): void => {
  const { f, path: p, rail } = w;
  const t0 = T.map;
  const at = (s: number): number => t0 + s;
  const L = LAYOUT;

  const ch = chapter(f, { key: "map", headline: MAP.headline, noStamp: true });
  runChapter(f, ch, "map");
  f.to(rail.root, { opacity: [1, 0] }, { at: t0 - EXIT, dur: EXIT, ease: "inQuad" });

  f.beat("map", t0, {
    title: MAP.headline,
    shows:
      "The opening path returns without the payload chips or the numbered circles. The ticket names drop onto the parts they build: FEE-890 on the route, ENG-2005 on the validate step, FEE-891 on the tests. Dashed marks the door and the later moves, which have no ticket yet.",
    talk: [pace("map", [MAP.headline, MAP.banner]).line],
  });

  // ---- the path comes back, cleared of what the opening used to tell its story
  f.set(p.markers, { opacity: 0 }, t0 - 0.01);
  f.to(p.root, { opacity: [0, 1] }, { at: t0, dur: 0.4, ease: "outQuad" });
  f.to(p.root, { opacity: [1, 0] }, { at: endOf("map") - EXIT, dur: EXIT, ease: "inQuad" });
  f.to(p.chips, { opacity: 0 }, { at: at(0.2), dur: 0.3, ease: "outQuad" });
  f.to(p.validateNote, { opacity: 0 }, { at: at(0.2), dur: 0.3, ease: "outQuad" });
  f.cls(p.steps[1], "now", { from: at(1.2) });
  f.cls(p.stems.slice(0, 2), "now", { from: at(1.2) });

  // ---- what each part is called in Linear
  const inRoute = (x: number, y: number): { x: number; y: number } => ({ x: x - L.route.x - 2.5, y: y - L.top - 2.5 });
  const routeAt = inRoute(L.route.x + L.route.w - 270, L.top + 8);
  const routePill = html(
    `<div class="ur-pill" data-card style="left:${routeAt.x}px;top:${routeAt.y}px">${esc(MAP.route)}</div>`,
  );
  // Centred on the validate step: two lines of 22 units in a pill are 65 units tall.
  const validateMid = L.step.y0 + (L.step.h + L.step.gap) + L.step.h / 2;
  const validatorsAt = inRoute(L.route.x + L.step.dx + L.step.w + 16, validateMid - 32.5);
  const validatorsPill = html(
    `<div class="ur-pill" data-card style="left:${validatorsAt.x}px;top:${validatorsAt.y}px">${esc(MAP.validators.replace(" · ", " ·\n"))}</div>`,
  );
  validatorsPill.style.whiteSpace = "pre";
  p.route.append(routePill, validatorsPill);

  const testsPill = html(
    `<div class="ur-pill" data-card style="left:${L.route.x + L.route.w + 12}px;top:${L.tests.y + (L.tests.h - 38) / 2}px">${esc(MAP.tests)}</div>`,
  );
  // The zone between plugin and route is 140 wide, so the door's label breaks into four short
  // lines. It hangs under the POST arrow: the door is where the call reaches the route.
  const doorLines = ["no", "ticket ·", "who is", "calling"];
  if (doorLines.join(" ") !== MAP.door) throw new Error("the door label no longer matches the data");
  const doorPill = html(
    `<div class="ur-pill dashed" data-card style="left:${L.zone.x1 + 12}px;top:${L.postY + 18}px;padding:3px 10px">${doorLines.map(esc).join("<br>")}</div>`,
  );
  p.root.append(testsPill, doorPill);

  // ---- the later moves, where the payload chips were: the plugin's flows are what move
  const ghost = html(
    `<div class="ur-ghost" data-card style="left:12px;top:${L.step.y0 - L.top - 2.5}px;width:${L.plugin.w - 29}px">${esc(MAP.later)}</div>`,
  );
  p.plugin.append(ghost);

  // ---- the key, and the line about until then
  const key = html(
    `<div class="ur-key"><span><i></i>${esc(MAP.legend[0])}</span><span><i class="dashed"></i>${esc(MAP.legend[1])}</span></div>`,
  );
  const banner = html(`<div class="ur-cap">${esc(MAP.banner)}</div>`);
  ch.root.append(key, banner);

  // ---- the order of things
  enter(f, key, at(0.7), { rise: 4 });
  enter(f, routePill, at(1.2), { rise: 6 });
  enter(f, validatorsPill, at(1.9), { rise: 6 });
