import { html } from "../../../engine/runtime";
import { esc } from "../../../kit";
import { PATH } from "../data";
import { appear, checkLegibility, draw, enter, land, leave, pace } from "../helpers";
import { EXIT, T, endOf } from "../timeline";
import { chapter, runChapter, type World } from "../world";

// Beat 1: the request path, drawn once. It comes back as the map in the last chapters.
export const requestPath = (w: World): void => {
  const { f, path: p } = w;
  const t0 = T.path;
  const at = (s: number): number => t0 + s;

  const ch = chapter(f, { key: "path", headline: PATH.headline, noStamp: true });
  runChapter(f, ch, "path");
  f.set(p.root, { opacity: 1 }, t0);
  f.to(p.root, { opacity: [1, 0] }, { at: endOf("path") - EXIT, dur: EXIT, ease: "inQuad" });

  const caps = PATH.captions.map((c) =>
    html(`<div class="ur-cap">${esc(c.text)}${c.tag ? `<small>${esc(c.tag)}</small>` : ""}</div>`),
  );
  ch.root.append(...caps);

  f.beat("path", t0, {
    title: PATH.headline,
    shows:
      "The path draws itself left to right: the plugin and its payload, the POST, the route and its four steps, the database, the response, the tests; then six numbered circles light up at their places on it.",
    talk: [pace("path", [PATH.headline, ...PATH.captions.map((c) => c.text)]).line],
  });

  // The plugin and its payload.
  enter(f, p.plugin, at(0.8));
  f.to(p.chips, { opacity: [0, 1], y: [-10, 0] }, { at: at(1.3), dur: 0.4, ease: "outBack", stagger: 0.15 });

  // The POST arrow into the route.
  enter(f, p.postLabel, at(2.1), { rise: 6 });
  draw(f, p.post.line, at(2.2), 0.6);
  appear(f, p.post.head, at(2.75), 0.15);
  enter(f, p.route, at(2.6));

  // The route's four steps; the one the draft does not have yet is dashed.
  f.to(p.steps, { opacity: [0, 1], y: [8, 0] }, { at: at(3.0), dur: 0.4, ease: "arrive", stagger: 0.28 });
  p.stems.forEach((stem, i) => appear(f, stem, at(3.28 + i * 0.28), 0.25));
  enter(f, p.validateNote, at(3.5), { rise: 4 });

