  draw(f, p.call.line, at(4.3), 0.5);
  appear(f, p.call.head, at(4.8), 0.15);
  enter(f, p.responseLabel, at(4.8), { rise: 6 });
  draw(f, p.response.line, at(4.9), 0.6);
  appear(f, p.response.head, at(5.45), 0.15);

