  enter(f, caps[0], at(1.0), { rise: 8 });
  leave(f, caps[0], at(5.0));
  enter(f, caps[1], at(5.5), { rise: 8 });
  leave(f, caps[1], at(9.0));
  enter(f, caps[2], at(9.4), { rise: 8 });

  // The six open places light up in the order of the chapters.
  p.markers.forEach((m, i) => land(f, m, at(9.4 + i * 0.33), 0.5));

  // Before the chapter starts to leave (EXIT before its end), when everything is in.
  checkLegibility(f, "path", [at(8.9), at(11.55)]);
