import { html } from "../../../engine/runtime";
import { esc } from "../../../kit";
import { NAME } from "../data";
import { checkLegibility, enter, land, pace } from "../helpers";
import { addressBar, card } from "../parts";
import { EXIT, T, endOf } from "../timeline";
import { chapter, railTo, runChapter, type World } from "../world";

// Chapter 2: what is the route called? Four names on record, in the order the brief
// lists them, each with who proposed it and when. No bar is marked as preferred; the
// colour is who, not good or bad.
export const name = (w: World): void => {
  const { f, rail } = w;
  const t0 = T.name;
  const at = (s: number): number => t0 + s;

  const ch = chapter(f, {
    key: "name",
    n: 2,
    headline: NAME.headline,
    tag: { text: NAME.tag },
    cols: { left: { x: 64, w: 636 }, right: { x: 730, w: 486 } },
  });
  runChapter(f, ch, "name");
  railTo(f, rail, 2, at(0.3));

  f.beat("name", t0, {
    title: `2 ${NAME.headline}`,
    shows:
      "Four browser-style address bars stack in, the draft's first, then Michael's, then Marc-Antoine's two, each tinted by who proposed it. Michael's two sentences about the name come in on the right.",
    talk: [pace("name", [NAME.headline, ...NAME.quotes]).line],
  });

  // ---- left: the four names
  const stack = html('<div class="ur-stack" style="gap:18px"></div>');
  const bars = NAME.bars.map((bar) => addressBar(bar));
  stack.append(...bars);
  ch.left.append(stack);

  // ---- right: Michael's words about the name
  const quote = card({ flow: true, who: "michael", tag: NAME.quoteTag, quote: NAME.quotes[0] });
  const second = html(`<p class="ur-quote">“${esc(NAME.quotes[1])}”</p>`);
  quote.append(second);
  const right = html('<div class="ur-stack"></div>');
  right.append(quote);
  ch.right.append(right);

  bars.forEach((bar, i) => enter(f, bar, at(0.5 + i * 0.5), { rise: 10 }));
  enter(f, quote, at(3.0));
  enter(f, second, at(6.0), { rise: 6 });
  land(f, ch.stamp, at(9.0), 0.8);
  if (ch.tag) enter(f, ch.tag, at(0.4), { rise: 6 });

  checkLegibility(f, "name", [at(9.6), endOf("name") - EXIT - 0.1]);
};
