// The slides that frame the film: the opening count, the three chapter cards, the recap, the
// three new tickets and the asks. HTML only; scenes-frame.ts animates what is built here.
import { esc } from "../../engine/runtime";
import {
  ALL_DECISIONS,
  ASKS,
  CHAPTERS,
  KCARD,
  OPEN,
  RECAP,
  TICKETS_SCENE,
  countStamps,
  isOpen,
  type RecapGroup,
  type StampKind,
} from "./data";
import { at, chapterPillHtml, countRowHtml, newTicketHtml, personHtml, rt, stampHtml, ticketLineHtml, type Rect } from "./parts";

const KINDS: StampKind[] = ["answer", "settled", "openMichael", "openMarc", "openSid"];

// A card that is dashed and empty at frame 0 and fills when its count arrives.
const countCard = (ref: string, r: Rect, body: string, bodyCls = ""): string =>
  `<div class="dc-ccard" data-ref="${ref}" style="${at(r)}"><div class="dc-ccard-fill" data-ref="${ref}-fill"></div><div class="dc-ccard-body${bodyCls ? ` ${bodyCls}` : ""}">${body}</div></div>`;

// ------------------------------------------------------------------ the count
export const slideOpen = (): string => {
  const counts = countStamps(ALL_DECISIONS);
  const openKinds = ["openMichael", "openMarc", "openSid"] as const;
  const openTotal = openKinds.reduce((sum, k) => sum + counts[k], 0);
  const chip = `<div class="dc-chip-wrap" style="top:100px"><div class="dc-pchip" data-ref="chip"><span class="dc-pchip-l">${esc(OPEN.chip.label)}</span><span>${esc(OPEN.chip.text)}</span></div></div>`;
  const a = countCard("a", { x: 56, y: 166, w: 1168, h: 84 }, countRowHtml("a-row", counts.answer, "answer", OPEN.glosses.answer));
  const b = countCard("b", { x: 56, y: 262, w: 1168, h: 84 }, countRowHtml("b-row", counts.settled, "settled", OPEN.glosses.settled));
  const o = countCard(
    "o",
    { x: 56, y: 358, w: 1168, h: 250 },
    `<div class="dc-bigcount" data-ref="o-big"><span class="dc-bigcount-n">${openTotal}</span><span class="dc-bigcount-l">${esc(OPEN.openLabel)}</span></div>` +
      `<div class="dc-rows">${openKinds.map((k, i) => countRowHtml(`o-r${i}`, counts[k], k)).join("")}</div>`,
    "dc-ccard-body--open",
  );
  const foot = `<div class="dc-sub24" data-ref="foot" style="left:56px;top:620px">${esc(OPEN.foot)}</div>`;
  return chip + a + b + o + foot + ticketLineHtml("tl", OPEN.tickets);
};

// ------------------------------------------------------------------ the chapter cards
export const slideK = (id: "k1" | "k2" | "k3"): string => {
  const k = KCARD[id];
  const chapter = CHAPTERS.find((c) => c.id === k.chapter);
  if (!chapter) throw new Error(`No chapter ${k.chapter}`);
  const counts = countStamps(chapter.decisions);
  const kinds = KINDS.filter((kind) => counts[kind] > 0);
  const rowH = 104;
  const gap = 12;
  const pad = 30;
  const h = kinds.length * rowH + (kinds.length - 1) * gap + pad * 2;
  const top = Math.round(432 - h / 2);
  const eyebrow = `<div class="dc-centered" style="top:${top - 70}px"><div class="dc-eyebrow dc-eyebrow--big" data-ref="eyebrow">${esc(k.eyebrow)}</div></div>`;
  const card = countCard(
    "card",
    { x: 190, y: top, w: 900, h },
    `<div class="dc-rows" style="gap:${gap}px">${kinds.map((kind, i) => countRowHtml(`r${i}`, counts[kind], kind, "", true)).join("")}</div>`,
    "dc-ccard-body--rows",
  );
  return eyebrow + card + ticketLineHtml("tl", k.tickets);
};

// ------------------------------------------------------------------ the recap
const recapGroup = (g: RecapGroup, ref: string): string => {
  const family = isOpen(g.kind) ? "open" : g.kind;
  const rows = g.rows
    .map(
      (r, i) =>
        `<div class="dc-rc-r dc-rc-r--${family}" data-ref="${ref}-r${i}"><span class="dc-rc-t">${rt(r.text, true)}</span></div>`,
    )
    .join("");
  return `<div class="dc-rc-g" data-ref="${ref}">${stampHtml(g.kind, { ref: `${ref}-stamp`, date: g.date })}${rows}</div>`;
};

export const slideRecap = (id: "recap1" | "recap2" | "recap3"): string => {
  const r = RECAP[id];
  const col = (groups: RecapGroup[], rect: Rect, ref: string): string =>
    `<div class="dc-rc" data-ref="${ref}" style="${at(rect)}">${groups.map((g, i) => recapGroup(g, `${ref}${i}`)).join("")}</div>`;
  return chapterPillHtml("chap", r.pill, true) + col(r.left, { x: 56, y: 104, w: 616 }, "L") + col(r.right, { x: 700, y: 104, w: 524 }, "R");
};

// ------------------------------------------------------------------ the three new tickets
// The three new tickets, and the one thing design.md says no ticket covers yet.
export const slideTickets = (): string => {
  const xs = [56, 448, 840];
  const cards = TICKETS_SCENE.cards
    .map((c, i) => newTicketHtml(`n${i}`, { x: xs[i], y: 96, w: 384, h: 322 }, c.id, c.tag ? [c.tag] : [], c.when))
    .join("");
  const gap =
    `<div class="dc-card dc-gap" data-ref="gap" style="${at({ x: 56, y: 438, w: 1168 })}">` +
    `<div class="dc-gap-h" data-ref="gap-h">${esc(TICKETS_SCENE.gap.head)}</div>` +
    `<div class="dc-gap-t" data-ref="gap-t">${rt(TICKETS_SCENE.gap.text, true)}</div></div>`;
  const foot = `<div class="dc-vd-t dc-foot32" data-ref="foot" style="left:56px;top:612px;width:1168px">${esc(TICKETS_SCENE.foot)}</div>`;
  return cards + gap + foot;
};

// ------------------------------------------------------------------ the asks
export const slideAsks = (): string => {
  const card = (ref: string, style: string, head: string, asks: string[], cls = ""): string =>
    `<div class="dc-card dc-ask${cls ? ` ${cls}` : ""}" data-ref="${ref}" style="${style}"><div class="dc-ask-h" data-ref="${ref}-head">${head}</div>${asks
      .map((a, i) => `<div class="dc-ask-q" data-ref="${ref}-q${i}">${rt(a, true).replace("{openMichael}", `<span class="dc-ask-stamp">${stampHtml("openMichael")}</span>`)}</div>`)
      .join("")}</div>`;
  const both = card(
    "both",
    at({ x: 56, y: 96, w: 1168 }),
    `<span class="dc-pair">${personHtml("michael")}${personHtml("marc")}</span><span>${esc(ASKS.both.who)}</span>`,
    ASKS.both.asks,
    "dc-ask--wide",
  );
  const flex = (basis: number): string => `flex:0 0 ${basis}px`;
  const row =
    `<div class="dc-askrow" data-ref="row" style="${at({ x: 56, y: 226, w: 1168 })}">` +
    card("michael", flex(480), `${personHtml("michael")}<span>${esc(ASKS.michael.who)}</span>`, ASKS.michael.asks, "dc-ask--sm") +
    card("marc", flex(340), `${personHtml("marc")}<span>${esc(ASKS.marc.who)}</span>`, ASKS.marc.asks, "dc-ask--sm") +
    card("sid", flex(308), `${personHtml("sid")}<span>${esc(ASKS.sid.who)}</span>`, ASKS.sid.asks, "dc-ask--sm") +
    `</div>`;
  return both + row;
};
